// ── L3a 대용량 업로드 스트리밍 (docs/PLAN-large-files-and-chunking §11.2) ──────────
// 큰 파일을 RAM에 통째로 올리지 않고(=`req.formData()`/`arrayBuffer()`의 1~2배 적재 회피)
// ★요청 본문을 청크 단위로 임시파일에 흘려보내며★ sha256·크기를 스트리밍 계산한다. 피크 메모리=청크.
// cap 초과는 스트림 중단·임시파일 삭제로 ★디스크 폭주 방지★. 서버 전용(node:fs/stream) — 클라 import 금지.
import { createWriteStream } from "node:fs";
import { mkdtemp, unlink, rm } from "node:fs/promises";
import { createHash } from "node:crypto";
import { Readable, Transform } from "node:stream";
import { pipeline } from "node:stream/promises";
import os from "node:os";
import path from "node:path";

export interface StreamedUpload {
  tempPath: string; // 임시파일 절대경로 — 호출측이 처리 후 ★반드시 cleanup★
  sha256: string;
  size: number;
}

// cap 초과 시그널 — 라우트가 413으로 매핑.
export class UploadTooLargeError extends Error {
  constructor(public limit: number) {
    super(`UPLOAD_TOO_LARGE:${limit}`);
    this.name = "UploadTooLargeError";
  }
}

function safeExt(ext?: string): string {
  const e = (ext || "").toLowerCase().replace(/[^a-z0-9]/g, "");
  return e || "bin";
}

/**
 * 웹 ReadableStream(또는 Node Readable)을 임시파일로 스트리밍하며 sha256·크기를 계산한다.
 * @param maxBytes 초과 시 UploadTooLargeError로 중단(임시파일 자동 삭제).
 * @returns 임시파일 경로·sha256·크기. ★tempPath는 호출측이 cleanupTemp로 정리할 책임★.
 */
export async function streamToTempFile(
  body: ReadableStream<Uint8Array> | Readable,
  maxBytes: number,
  ext?: string,
): Promise<StreamedUpload> {
  const dir = await mkdtemp(path.join(os.tmpdir(), "llmwiki-up-"));
  const tempPath = path.join(dir, `upload.${safeExt(ext)}`);
  const hash = createHash("sha256");
  let size = 0;

  // pipeline 중간 Transform: 해시·크기 누적 + cap 강제(초과 시 에러로 파이프라인 전체 중단·정리).
  const meter = new Transform({
    transform(chunk: Buffer, _enc, cb) {
      size += chunk.length;
      if (size > maxBytes) {
        cb(new UploadTooLargeError(maxBytes));
        return;
      }
      hash.update(chunk);
      cb(null, chunk);
    },
  });

  const src: Readable = body instanceof Readable ? body : Readable.fromWeb(body as Parameters<typeof Readable.fromWeb>[0]);
  const out = createWriteStream(tempPath);
  try {
    await pipeline(src, meter, out);
  } catch (err) {
    await rm(dir, { recursive: true, force: true }).catch(() => {});
    throw err;
  }
  return { tempPath, sha256: hash.digest("hex"), size };
}

// 임시파일(과 그 디렉터리) 정리 — 처리 완료/실패 후 호출.
export async function cleanupTemp(tempPath: string): Promise<void> {
  try {
    await unlink(tempPath).catch(() => {});
    await rm(path.dirname(tempPath), { recursive: true, force: true }).catch(() => {});
  } catch {
    /* best-effort */
  }
}

