 // PDF·문서를 ★원본 그대로(네이티브)★ 모델에 첨부할 수 있는 공급자 — 표·레이아웃을 모델이 직접 읽는다.
 //   anthropic·gemini만 지원(ollama는 무시, openai-compat/Groq는 문서 전송 미구현).
@@ -34,6 +39,13 @@ function supportsNativeDocs(provider: string): boolean {
   return provider === "anthropic" || provider === "gemini";
 }

+// 음성·영상 소스 판별 — 미분석(전사 실패)이라 extractor가 groq-/gemini-가 아니어도 raw 재전사 대상으로 잡기 위함.
+const AUDIO_VIDEO_EXTS = ["mp3", "m4a", "wav", "flac", "ogg", "mpga", "mp4", "mpeg", "webm", "mov", "mkv", "avi", "aac", "wma"];
+function isAudioVideoExt(ext: string, mime?: string | null): boolean {
+  if (mime?.startsWith("audio/") || mime?.startsWith("video/")) return true;
+  return AUDIO_VIDEO_EXTS.includes(ext.toLowerCase());
+}
+
 // 인제스트 편집셋 ★출력 토큰 상한★ — 잘림(MAX_TOKENS로 편집셋 truncate)을 줄이려 ★공급자 최대 출력★을 기본으로.
 //   env INGEST_MAX_TOKENS로 조정 가능하나, 공급자 최대를 넘기면 API 400 → cap으로 클램프한다.
 //   gemini-2.5-flash=65536(최대), 그 외(claude/groq 등)는 안전하게 기존 32768 유지.
@@ -764,7 +776,6 @@ const frontmatterOf = (rec: Record<string, string>) => `---\n${Object.entries(re
 // ★분석 비용 footer★ — 이번 분석으로 생성된 콘텐츠 페이지(entities/concepts/topics)에
 //   '분석 모델·사용 토큰'을 코드가 멱등하게 단다(마커로 재분석 시 교체). 같은 자료 1회 분석에서 나온
 //   페이지들은 그 분석의 총 토큰을 공유한다(자료 단위 비용). recordUsage(DB)와 별개로 ★위키에 남기는★ 용도.
-const AI_COST_RE = /\n*<!-- ai-cost -->[\s\S]*$/;
 async function stampAnalysisCost(changed: string[], model: string, inT: number, outT: number): Promise<void> {
   const when = kstStamp(); // 한국 시간(KST) 초 단위 — '분석/업데이트 시간'
   const footer = `\n\n<!-- ai-cost -->\n> 🤖 분석 모델: ${model} · 토큰 입력 ${inT.toLocaleString()} · 출력 ${outT.toLocaleString()} · ${when}\n`;
@@ -772,7 +783,7 @@ async function stampAnalysisCost(changed: string[], model: string, inT: number,
   for (const rel of pages) {
     const abs = wikiAbsPath(rel);
     try {
-      const body = (await fs.readFile(abs, "utf8")).replace(AI_COST_RE, "").replace(/\s+$/, "");
+      const body = stripAiCostFooter(await fs.readFile(abs, "utf8")); // 기존 푸터 제거(멱등) — 공용 헬퍼로 통일
       await atomicWriteFile(abs, body + footer); // 원자적
     } catch { /* 페이지 없으면 건너뜀 */ }
   }
@@ -857,6 +868,41 @@ export async function storeForAnalysis(input: IngestInput): Promise<StageResult>
  * [분석] — 스테이징된 원본을 ★실제 LLM 인제스트★. 보관된 raw/normalized를 다시 읽어 ingestText에 넘긴다.
  * ingestText의 dedup이 APPLIED 잡 없는 스테이징 소스를 정리 후 새로 만들므로 중복 없이 교체된다.
  */
+// L3b 디제스트 시스템 — 요약이 아니라 ★지식 보존 추출★(개체·사실·수치·결정). 정보는 버리지 않는다.
+const DIGEST_SYSTEM = "당신은 긴 문서를 사내 위키 지식으로 정리하기 전, 한 부분(섹션)에서 ★핵심 지식을 빠짐없이 추출★하는 도우미입니다. 인물·조직·제품·시스템 같은 개체, 사실·수치·날짜·금액, 정의·결정·합의·액션아이템을 항목으로 보존하세요. 인사말·중복·군더더기는 빼되 ★정보는 절대 버리지 마세요★. 출력은 간결한 한국어 markdown 불릿 위주.";
+
+// 거대 텍스트를 모델 컨텍스트에 맞게 ★map-reduce 응축★(docs/PLAN §11.3). ingestText 코어는 건드리지 않고,
+//   analyzeSource가 ingestText에 넘기기 ★전★ 이 함수로 줄인다. ★예산 이하면 LLM 호출 없이 원문 그대로★(불변·비용0).
+async function condenseTextForIngest(text: string, ctx: { model?: string; provider?: string; signal?: AbortSignal; jobId?: number }): Promise<string> {
+  const provider = ctx.provider ?? providerFor("ingest");
+  const budget = chunkBudgetChars(promptTier(provider), provider); // 공급자 실제 컨텍스트 기준 — 대부분 단일 패스(무손실)
+  if (text.length <= budget) return text; // ★빠른 경로 — 대부분 문서는 여기서 그대로 반환(회귀 0)★
+  await loadSecrets();
+  const model = ctx.model ?? MODELS.ingest;
+  const disabled = await disabledModelIds();
+  const fallbacks = fallbackChainFor(model, provider).filter((f) => !disabled.has(f.model));
+  const DIGEST_SCHEMA = { type: "object", additionalProperties: false, required: ["digest"], properties: { digest: { type: "string", description: "이 부분의 핵심 지식(개체·사실·수치·결정) 추출 markdown" } } } as Record<string, unknown>;
+  const summarize: Summarizer = async (chunk, idx, total) => {
+    if (ctx.signal?.aborted) throw new Error("취소됨");
+    if (ctx.jobId != null) {
+      // 진행률: 응축은 분석 전반부(0~50%)로 표시 — MaterialsTab 폴링이 "요약 k/N"을 보여준다.
+      await prisma.ingestJob.update({ where: { id: ctx.jobId }, data: { phase: `요약 ${idx + 1}/${total}`, progress: Math.round(((idx + 1) / total) * 50) } }).catch(() => {});
+    }
+    const r = await callStructured<{ digest: string }>({
+      model, provider, fallbacks, signal: ctx.signal,
+      system: DIGEST_SYSTEM,
+      userText: `다음은 긴 문서의 ${idx + 1}/${total} 부분입니다. 위키 정리에 필요한 핵심 지식을 빠짐없이 추출하세요(정보 보존):\n\n${chunk}`,
+      toolName: "submit_digest",
+      toolDescription: "핵심 지식 추출(JSON).",
+      schema: DIGEST_SCHEMA,
+      maxTokens: ingestMaxTokens(provider),
+    });
+    return `## ${idx + 1}부\n${r.data.digest}`;
+  };
+  const result = await condenseToFit(text, budget, summarize);
+  return result.text;
+}
+
 export async function analyzeSource(sourceId: number, opts: { model?: string; provider?: string; think?: boolean; signal?: AbortSignal; diarize?: boolean; meeting?: boolean; jobId?: number }): Promise<IngestResult> {
   const source = await prisma.source.findUnique({ where: { id: sourceId } });
   if (!source) throw new Error("자료를 찾을 수 없습니다.");
@@ -897,6 +943,42 @@ export async function analyzeSource(sourceId: number, opts: { model?: string; pr
     if (!extracted && source.normalizedPath) {
       try { extracted = await fs.readFile(wikiAbsPath(source.normalizedPath), "utf8"); } catch { /* */ }
     }
+    const hasUsableText = extracted.trim().length >= 120; // pdfjs 'full' 기준 — 이 미만이면 스캔/이미지 PDF로 본다.
+
+    // ── 스캔/이미지 PDF(텍스트 없음): 페이지 래스터 + 다운스케일 → ‘이미지’로 분석(gemini·codex 공통) ──
+    //   원본 PDF 직접 첨부는 codex가 못 받고 Gemini도 초고해상도면 400 → 페이지를 적정 해상도 이미지로 줄여 보낸다.
+    //   ★다운스케일은 분석 입력만★ — 원본(raw)은 보존되므로 영구 품질 손실이 아니다(사용자에게 명시·docs §6.7).
+    if (!hasUsableText) {
+      let raster: Awaited<ReturnType<typeof extractPdfPageImages>> | null = null;
+      try { raster = await extractPdfPageImages(rawBytes, { signal: opts.signal }); } catch { /* 래스터 실패 → 아래 폴백 */ }
+      if (raster && raster.images.length) {
+        // ★페이지별 비전 전사 → 텍스트★(docs §6.7 Option A): 빽빽한 다중페이지를 한 번에 분석하면 편집셋 출력이
+        //   토큰 한도를 넘겨 잘린다 → 페이지마다 따로 전사(출력 한정)해 합친 뒤, 기존 텍스트 인제스트(L3b 응축)로 처리.
+        const ocr = await transcribeScannedPages(raster.images, { model: opts.model ?? MODELS.ingest, provider, signal: opts.signal });
+        if (ocr.text.trim()) {
+          const dnote = raster.downscaled ? `(분석을 위해 페이지를 최대 ${raster.maxEdge}px로 다운스케일해 전사 — ★원본은 그대로 보존★)` : "(페이지 이미지에서 전사)";
+          const tnote = raster.truncated ? ` 앞 ${ocr.pages}페이지만 반영합니다(나머지 ${raster.truncated}페이지 생략).` : "";
+          // 합친 전사 텍스트는 거대할 수 있으니 ★L3b 응축★ 후 인제스트(사이드카엔 전사 원문 보존).
+          const condensed = await condenseTextForIngest(ocr.text, { model: opts.model, provider, signal: opts.signal, jobId: opts.jobId });
+          const header = `[스캔 PDF '${source.originalName ?? source.title}' — ${ocr.pages}/${raster.pageCount}페이지를 이미지에서 전사 ${dnote}.${tnote}]\n\n`;
+          return ingestText({ ...base, type: "PDF", rawExt: "pdf",
+            extractor: `pdf-scan-ocr@${raster.maxEdge}px`,
+            extractStatus: raster.truncated ? "PARTIAL" : "FULL",
+            text: header + condensed,
+            normalizedText: ocr.text, // 전사 원문 사이드카 보존(다시 더 정밀 분석 가능)
+            augment, preservePath });
+        }
+        // 전사 결과가 비었으면(진짜 빈 스캔 등) 아래 폴백으로.
+      }
+      // 래스터화 0장(벡터-only·이상 PDF 등) → 폴백: 비-네이티브는 정직한 실패, gemini/anthropic은 아래 native 첨부로 시도.
+      if (!supportsNativeDocs(provider)) {
+        throw new Error(
+          `이 자료는 텍스트도 페이지 이미지도 추출할 수 없는 스캔/이미지 PDF입니다. 현재 모델(${opts.model ?? provider})로는 분석할 수 없습니다 — Gemini(또는 Claude)로 시도하세요.`,
+        );
+      }
+    }
