index 0000000..d9d795d
--- /dev/null
+++ b/lib/jobs/reconcile.ts
@@ -0,0 +1,45 @@
+import { prisma } from "../db";
+
+// ── 고아 잡 회수 (R2) ────────────────────────────────────────────────────────
+// 워커 크래시·서버 재시작이 인제스트 도중 일어나면 IngestJob이 RUNNING/QUEUED/APPLYING로 박제된다
+//   (pg-boss 메시지는 끝났는데 DB 행이 안 바뀜 → UI가 "요약 1/3"에서 영원히 멈춤). 실제 발생 사례.
+// → 워커 부팅 시 ★오래(>maxAge) 갱신 없는★ 진행상태 잡을 FAILED로 회수해 [재처리] 가능하게 한다.
+//   ★멀티파드 안전★: 살아있는 워커는 그 안에 phase를 갱신(updatedAt 최신)하거나 R1 타임아웃(≤수분)으로
+//   곧 종결되므로, maxAge(기본 30분=pg-boss expireInSeconds)보다 오래 멈춘 잡은 ‘죽은 것’으로 확정 가능.
+//   (docs/PLAN-multi-upload-and-progress §R2)
+
+export interface StuckCandidate { id: number; status: string; updatedAt: Date }
+const STUCK_STATUSES = new Set(["QUEUED", "RUNNING", "APPLYING"]);
+
+// 순수: 진행상태(QUEUED/RUNNING/APPLYING)이면서 maxAgeMs보다 오래 갱신 없는 잡 id들. 테스트 가능.
+export function selectStuckJobs(jobs: StuckCandidate[], nowMs: number, maxAgeMs: number): number[] {
+  return jobs
+    .filter((j) => STUCK_STATUSES.has(j.status) && nowMs - j.updatedAt.getTime() > maxAgeMs)
+    .map((j) => j.id);
+}
+
+function stuckMaxAgeMs(): number {
+  return Number(process.env.INGEST_STUCK_MAX_AGE_MS || 0) || 1_800_000; // 30분(pg-boss expireInSeconds와 정렬)
+}
+
+// 부팅 시 1회: 오래 멈춘 진행상태 잡을 FAILED로 회수. 실패해도 워커 부팅을 막지 않음(best-effort).
+export async function reconcileStuckJobs(): Promise<number> {
+  try {
+    const candidates = await prisma.ingestJob.findMany({
+      where: { status: { in: ["QUEUED", "RUNNING", "APPLYING"] } },
+      select: { id: true, status: true, updatedAt: true },
+    });
+    const stuck = selectStuckJobs(candidates, Date.now(), stuckMaxAgeMs());
+    if (stuck.length) {
+      await prisma.ingestJob.updateMany({
+        where: { id: { in: stuck } },
+        data: { status: "FAILED", error: "서버 재시작/중단으로 처리가 끊겼습니다. [재처리]로 다시 시도하세요." },
+      });
+      console.log(`[reconcile] 멈춘 잡 ${stuck.length}건 FAILED 회수: ${stuck.join(",")}`);
+    }
+    return stuck.length;
+  } catch (err) {
+    console.error("[reconcile] 고아 잡 회수 실패(무시):", String(err));
+    return 0;
+  }
+}

