+// ai-cost 푸터 = 페이지를 ★어떤 모델·토큰·언제 분석했는지★의 출처 메타데이터(stampAnalysisCost가 단다).
+//   이건 ★코드가 관리하는 메타데이터★라 사람/LLM 편집이 건드리면 안 된다(건드리면 분석 출처 이력이 사라짐).
+//   AI 보조편집 때 LLM에는 ★본문만★ 주고, 원래 푸터는 그대로 되붙여 출처를 보존한다. (메모리 human-readable-attribution)
+
+export const AI_COST_MARKER = "<!-- ai-cost -->";
+
+// 본문과 ai-cost 푸터를 분리. 푸터 없으면 footer="". (마커부터 끝까지를 푸터로 본다 — 보통 페이지 맨 끝.)
+export function splitAiCostFooter(md: string): { body: string; footer: string } {
+  const idx = md.indexOf(AI_COST_MARKER);
+  if (idx < 0) return { body: md.replace(/\s+$/, ""), footer: "" };
+  const body = md.slice(0, idx).replace(/\s+$/, "");
+  const footer = md.slice(idx).replace(/\s+$/, "");
+  return { body, footer };
+}
+
+// 본문에서 ai-cost 푸터 제거(있으면). stampAnalysisCost가 새 푸터를 달기 전 기존 푸터를 떼는 데도 쓴다.
+export function stripAiCostFooter(md: string): string {
+  return splitAiCostFooter(md).body;
+}
+
+// 재작성된 본문에 ★원래 푸터를 그대로★ 되붙인다(출처 보존). 푸터 없으면 본문만.
+export function reattachAiCostFooter(body: string, footer: string): string {
+  const clean = body.replace(/\s+$/, "");
+  return footer ? `${clean}\n\n${footer}\n` : clean;
+}

