// ── L3b 거대 문서 응축 (docs/PLAN-large-files-and-chunking §11.3) ─────────────────────
// 추출 텍스트가 모델 컨텍스트(토큰 예산)를 넘으면 ★map-reduce 응축★으로 한 프롬프트 한계를 우회한다:
//   ① 섹션 경계로 청크 분할(lib/chunk) → ② 청크별 '핵심 지식 추출'(요약 아님 — 개체·사실·수치·결정 보존)
//   → ③ 추출본을 이어붙여 다시 예산 초과면 재귀 축약 → ④ ★예산에 맞는 단일 텍스트★를 기존 ingestText에 그대로.
// ingestText 코어는 ★무변경★ — 작은 문서는 응축을 건너뛰어 동작이 100% 동일하다(회귀 0).
// 순수 오케스트레이션(LLM 호출은 ★주입★ — summarize 콜백)이라 단위 테스트가 쉽다.
import { chunkTextBySections } from "./chunk";

export interface CondenseResult {
  text: string; // 예산에 맞는(또는 더 못 줄이는) 최종 텍스트
  rounds: number; // 축약 라운드 수(0=응축 안 함)
  condensed: boolean; // 한 번이라도 축약했나
  chunks: number; // 첫 라운드 청크 수(진행률 표시용)
}

// 청크 1개 → 핵심 지식 추출문. (chunk, idx, total, round) 받아 압축 텍스트 반환.
export type Summarizer = (chunk: string, idx: number, total: number, round: number) => Promise<string>;

/**
 * text가 budget 이하면 그대로(응축 안 함). 초과면 청크별 summarize로 줄여 budget에 맞춘다.
 * - 더 못 쪼개거나(단일 청크) maxRounds 도달 시 중단(그 시점 텍스트 반환 — ingestText의 413 축소가 보조).
 * - ★budget 이하 입력은 summarize를 절대 호출하지 않는다★ → 작은 문서 비용·동작 불변.
 */
export async function condenseToFit(
  text: string,
  budget: number,
  summarize: Summarizer,
  maxRounds = 3,
): Promise<CondenseResult> {
  if (budget <= 0 || text.length <= budget) return { text, rounds: 0, condensed: false, chunks: 1 };
  let cur = text;
  let rounds = 0;
  let firstChunks = 0;
  while (cur.length > budget && rounds < maxRounds) {
    const chunks = chunkTextBySections(cur, budget);
    if (chunks.length <= 1) break; // 더 못 나눔 → 중단(ingestText 413 축소가 마지막 방어)
    if (rounds === 0) firstChunks = chunks.length;
    const digests: string[] = [];
    for (let i = 0; i < chunks.length; i++) {
      digests.push(await summarize(chunks[i], i, chunks.length, rounds));
    }
    cur = digests.join("\n\n");
    rounds++;
  }
  return { text: cur, rounds, condensed: rounds > 0, chunks: firstChunks || 1 };
}

