import { callStructured } from "./anthropic";
import type { PdfPageImage } from "./pdf-images";

// ─────────────────────────────────────────────────────────────────────────────
// 스캔 PDF ★페이지별 비전 전사★ (docs/PLAN-model-prompt-strategy §6.7, Option A).
//
// 왜: 다운스케일한 페이지들을 한 번에 인제스트하면 편집셋 출력이 65K 토큰을 넘겨 잘린다(실측: 9920px 4페이지).
//   → 각 페이지를 ★따로 전사(OCR)★해 markdown 텍스트로 만들면 호출당 출력이 한 페이지로 한정된다(초과 없음).
//   합친 텍스트는 ★기존 텍스트 인제스트(L3b 응축 포함)★가 그대로 처리 → editSet 병합 위험([[large-doc-mapreduce-condense]]) 회피.
// ─────────────────────────────────────────────────────────────────────────────

const TRANSCRIBE_SCHEMA = {
  type: "object",
  properties: {
    markdown: { type: "string", description: "이 페이지에 보이는 모든 텍스트·표·수치·라벨을 빠짐없이 옮긴 markdown(표는 markdown 표). 텍스트가 없으면 빈 문자열." },
  },
  required: ["markdown"],
} as const;

// 순수: 페이지별 전사문을 ★페이지 머리글과 함께★ 하나로 합친다(빈 페이지는 제외). 테스트 가능.
export function joinPageTranscripts(transcripts: string[]): { text: string; pages: number } {
  const blocks: string[] = [];
  for (let i = 0; i < transcripts.length; i++) {
    const m = (transcripts[i] ?? "").trim();
    if (m) blocks.push(`## (스캔 페이지 ${i + 1})\n\n${m}`);
  }
  return { text: blocks.join("\n\n"), pages: blocks.length };
}

// 페이지 이미지들을 ★제한 동시성★으로 비전 전사 → 합쳐 markdown 반환. 각 호출 출력은 maxTokens로 한 페이지에 한정.
export async function transcribeScannedPages(
  images: PdfPageImage[],
  opts: { model: string; provider: string; signal?: AbortSignal; concurrency?: number },
): Promise<{ text: string; pages: number }> {
  const conc = opts.concurrency ?? (Number(process.env.PDF_OCR_CONCURRENCY || 0) || 2); // 무료 등급 RPM 보호 위해 기본 2
  const maxTokens = Number(process.env.PDF_OCR_MAX_TOKENS || 0) || 16384; // 한 페이지 전사 상한(초과 방지)
  const out: string[] = new Array(images.length).fill("");
  let next = 0;

  const worker = async (): Promise<void> => {
    for (;;) {
      const i = next++;
      if (i >= images.length) return;
      if (opts.signal?.aborted) throw new Error("분석이 취소되었습니다.");
      const im = images[i];
      const r = await callStructured<{ markdown: string }>({
        model: opts.model,
        provider: opts.provider,
        images: [{ mediaType: im.mediaType, dataBase64: im.dataBase64 }],
        system:
          "너는 스캔 문서를 정확히 옮기는 전사기(OCR)다. 이미지에 보이는 ★모든 텍스트·표·수치·라벨★을 빠짐없이 markdown으로 옮긴다. " +
          "표는 markdown 표로 복원한다. ★추측·요약·생략 금지★ — 보이는 그대로. 글자가 없으면 빈 문자열.",
        userText: `이 스캔 페이지(${i + 1}/${images.length})를 markdown으로 전사하라.`,
        toolName: "submit_transcription",
        toolDescription: "전사한 markdown",
        schema: TRANSCRIBE_SCHEMA,
        maxTokens,
        signal: opts.signal,
      });
      out[i] = (r.data.markdown ?? "").trim();
    }
  };

  await Promise.all(Array.from({ length: Math.min(conc, images.length) }, () => worker()));
  return joinPageTranscripts(out);
}

