// ── LLM HTTP 호출 타임아웃 (R1) ──────────────────────────────────────────────
// Groq/Gemini/OpenAI 등 외부 LLM fetch가 한도(429)·과부하·네트워크 지연으로 ★응답을 끝없이 붙들면★
//   인제스트 잡이 "요약 1/3" 등에서 영원히 박제된다(타임아웃 부재 = hang). 실제로 68분 음성 전사가
//   Groq 시간당 한도를 소진한 뒤 이어진 응축 호출이 hang해 잡이 멈춘 사례. (docs/PLAN-multi-upload-and-progress §R1)
// → 모든 LLM fetch에 ★유한 타임아웃★을 건다. 타임아웃이면 abort → 호출측 try/catch가 폴백/실패로 전환(박제 방지).
//   호출 취소 신호(opts.signal)와 OR로 결합해, 사용자가 취소해도·타임아웃이어도 즉시 중단된다.

export function llmTimeoutMs(): number {
  return Number(process.env.LLM_HTTP_TIMEOUT_MS || 0) || 180_000; // 기본 3분(대형 분석 여유 + hang 차단)
}

// 취소 신호(있으면)와 타임아웃을 합친 AbortSignal. Node 18+ AbortSignal.any/timeout 사용.
export function fetchAbort(signal?: AbortSignal | null, ms: number = llmTimeoutMs()): AbortSignal {
  const timeout = AbortSignal.timeout(ms);
  return signal ? AbortSignal.any([signal, timeout]) : timeout;
}

// fetch 거부가 ★타임아웃★ 때문인지 판별(사용자 취소 vs 시간초과 메시지 구분용).
export function isTimeoutAbort(e: unknown): boolean {
  return e instanceof DOMException && e.name === "TimeoutError";
}

