import { NextResponse } from "next/server";
import { getSessionUser } from "@/lib/auth/session";
import { retentionConfig, previewRawRetention, evictRawForSources } from "@/lib/jobs/retention";

// L4 대용량 원본 보존정책(docs/PLAN §11.6) — ★관리자 수동 + 미리보기/확인★(자율 cron 삭제 아님).
//   GET=미리보기(읽기 전용, 무엇이·얼마나 정리되는지), POST=확인한 id만 실제 정리(원본 바이트만, 지식 보존).
//   기본 OFF(RETENTION_RAW_DAYS 미설정/0) → 미리보기가 enabled:false 반환.
export const runtime = "nodejs";

export async function GET() {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
  if (user.role !== "ADMIN") return NextResponse.json({ error: "관리자만 사용할 수 있습니다." }, { status: 403 });
  const cfg = retentionConfig();
  const preview = await previewRawRetention(cfg);
  return NextResponse.json({ config: { days: cfg.days, minMb: Math.round(cfg.minBytes / 1024 / 1024) }, ...preview });
}

export async function POST(req: Request) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
  if (user.role !== "ADMIN") return NextResponse.json({ error: "관리자만 사용할 수 있습니다." }, { status: 403 });
  const cfg = retentionConfig();
  if (cfg.days <= 0) return NextResponse.json({ error: "보존정책이 비활성입니다(RETENTION_RAW_DAYS 미설정)." }, { status: 400 });
  const body = await req.json().catch(() => ({}));
  const ids = Array.isArray(body.ids) ? body.ids.filter((x: unknown): x is number => Number.isInteger(x)) : [];
  if (!ids.length) return NextResponse.json({ error: "정리할 자료 id가 필요합니다(미리보기에서 선택)." }, { status: 400 });
  // ★확인된 id만★ 실제 정리(evictRawForSources가 시점차·미분석 가드를 다시 확인).
  const result = await evictRawForSources(ids);
  return NextResponse.json({ ok: true, ...result });
}

