"use client";

import { confirmDialog } from "@/components/ui/Dialog";

import { useEffect, useState } from "react";
import { IconChartBar, IconShieldHalf, IconRefresh, IconDeviceFloppy } from "@tabler/icons-react";

interface ModelUse { model: string; todayTokens: number; todayRequests: number; weekTokens: number; weekRequests: number }
interface Row {
  userId: number; name: string; email: string; role: string; active: boolean;
  todayTokens: number; todayRequests: number; weekTokens: number; weekRequests: number; models: ModelUse[];
}
const fmt = (n: number) => n.toLocaleString();
const shortM = (id: string) => (id.includes("/") ? id.slice(id.lastIndexOf("/") + 1) : id);

type LimitKind = "dailyLimit" | "scopeLimit" | "globalLimit";

// 상한 입력 한 줄(사용자/룸/전체 공용). 저장은 그 키만 부분 업데이트.
function LimitRow({ label, kind, value, hint, onSaved }: {
  label: string; kind: LimitKind; value: number; hint: string; onSaved: (v: number) => void;
}) {
  const [input, setInput] = useState(String(value));
  const [saving, setSaving] = useState(false);
  const [note, setNote] = useState("");
  useEffect(() => { setInput(String(value)); }, [value]);
  async function save() {
    const n = Number(input);
    if (!Number.isFinite(n) || n < 0) { setNote("0 이상 숫자를 입력하세요."); return; }
    setSaving(true); setNote("");
    try {
      const r = await fetch("/api/admin/usage", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ [kind]: n }) });
      const d = await r.json();
      if (!r.ok) throw new Error(d.error || "저장 실패");
      onSaved(d[kind] || 0);
      setNote((d[kind] || 0) > 0 ? `${fmt(d[kind])} 토큰/일 적용됨 ✓` : "무제한으로 설정됨 ✓");
      setTimeout(() => setNote(""), 3000);
    } catch (e) { setNote(e instanceof Error ? e.message : String(e)); }
    finally { setSaving(false); }
  }
  return (
    <>
      <div className="au-limit">
        <span className="au-limit-lbl">{label}</span>
        <input className="au-limit-input" type="number" min={0} step={1000} value={input}
          onChange={(e) => setInput(e.target.value)} placeholder="0 = 무제한" disabled={saving} />
        <button className="au-limit-save" onClick={save} disabled={saving || input === String(value)}>
          <IconDeviceFloppy size={14} />{saving ? "저장 중…" : "저장"}
        </button>
        <span className="au-limit-cur">현재: {value > 0 ? `${fmt(value)} 토큰/일` : "무제한"}</span>
        {note && <span className="au-limit-note">{note}</span>}
      </div>
      <p className="set-note" style={{ marginTop: -2 }}>{hint}</p>
    </>
  );
}

export default function UsageConsole(_props: { onClose?: () => void } = {}) {
  const [rows, setRows] = useState<Row[]>([]);
  const [dailyLimit, setDailyLimit] = useState(0);
  const [scopeLimit, setScopeLimit] = useState(0);
  const [globalLimit, setGlobalLimit] = useState(0);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState<string | null>(null);
  const [backfilling, setBackfilling] = useState(false);
  const [backfillNote, setBackfillNote] = useState("");
  const [backfillPending, setBackfillPending] = useState(0); // updated가 날짜만인 페이지 수 — 0이면 버튼 숨김(1회성)

  async function load() {
    setLoading(true); setErr(null);
    try {
      const r = await fetch("/api/admin/usage", { cache: "no-store" });
      const d = await r.json();
      if (!r.ok) throw new Error(d.error || "불러오기 실패");
      setRows(d.users || []);
      setDailyLimit(d.dailyLimit || 0); setScopeLimit(d.scopeLimit || 0); setGlobalLimit(d.globalLimit || 0);
    } catch (e) {
      setErr(e instanceof Error ? e.message : String(e));
    } finally { setLoading(false); }
  }
  // 백필이 필요한(날짜만) 페이지 수 — 있을 때만 '위키 시각 보정' 버튼을 보인다(다 끝나면 사라짐).
  async function checkBackfill() {
    try { const r = await fetch("/api/admin/wiki-backfill", { cache: "no-store" }); const d = await r.json(); if (r.ok) setBackfillPending(d.pending || 0); } catch { /* noop */ }
  }
  useEffect(() => { load(); checkBackfill(); }, []);

  // 기존 위키 페이지의 updated(날짜만)를 마지막 변경 시각(KST 초)으로 일괄 보정 — 서버 접속 없이 앱에서 실행.
  async function runBackfill() {
    if (backfilling) return;
    if (!await confirmDialog("기존 위키 페이지의 ‘수정 시각(updated)’이 날짜만 적힌 것을 각 페이지의 마지막 변경 시각(한국 시간·초)으로 보정합니다.\n이미 초 단위인 페이지는 그대로 둡니다. 진행할까요?")) return;
    setBackfilling(true); setBackfillNote("");
    try {
      const r = await fetch("/api/admin/wiki-backfill", { method: "POST" });
      const d = await r.json();
      if (!r.ok) throw new Error(d.error || "실패");
      setBackfillNote(d.changed > 0 ? `${fmt(d.changed)}개 페이지 보정됨 ✓ (검사 ${fmt(d.scanned)})` : `보정할 항목 없음 — 이미 모두 초 단위 (검사 ${fmt(d.scanned)})`);
      checkBackfill(); // 남은 수 갱신 → 0이면 버튼이 사라짐
    } catch (e) { setBackfillNote(e instanceof Error ? e.message : String(e)); }
    finally { setBackfilling(false); }
  }

  const todayTotal = rows.reduce((s, r) => s + r.todayTokens, 0);
  const weekTotal = rows.reduce((s, r) => s + r.weekTokens, 0);
  const activeUsers = rows.filter((r) => r.weekTokens > 0).length;
  const maxToday = Math.max(1, ...rows.map((r) => r.todayTokens));

  return (
    <div className="set-page"><div className="set-wrap">
      <h1 className="set-title"><IconChartBar size={20} style={{ verticalAlign: "-3px", marginRight: 8 }} />사용량 (관리자)</h1>
      <p className="set-note" style={{ marginTop: -6 }}>
        전체 사용자의 토큰·요청을 모델별로 봅니다(<b>오늘 / 최근 7일</b>, 한국 시간 기준). 토큰 절약 경각심·과사용 점검용.
      </p>

      {/* 일일 토큰 상한 3단계(REQ-OPS-006) — 초과 시 질의·업로드가 자동 차단됨. 가장 제한적인 단계가 먼저 걸린다. */}
      <LimitRow label="사용자별 1일 토큰 상한" kind="dailyLimit" value={dailyLimit} onSaved={setDailyLimit}
        hint="한 사용자의 그날 합계가 넘으면 그 사용자만 차단(다음 날 0시 KST 리셋)." />
      <LimitRow label="룸(scope)별 1일 토큰 상한" kind="scopeLimit" value={scopeLimit} onSaved={setScopeLimit}
        hint="한 룸의 그날 합계가 넘으면 그 룸의 질의·인제스트가 차단. 룸 단위 과사용 방지." />
      <LimitRow label="전체 1일 토큰 상한" kind="globalLimit" value={globalLimit} onSaved={setGlobalLimit}
        hint="모든 사용자·룸 합계가 넘으면 전면 차단. ★공유 API 키 총비용 폭주 가드★(0 = 무제한)." />

      {/* 위키 시각 보정 — ★1회성★. 날짜만인 페이지가 남아 있을 때만 노출하고, 다 끝나면 사라진다. */}
      {(backfillPending > 0 || backfillNote) && (
        <>
          <div className="au-limit" style={{ marginTop: 4 }}>
            <span className="au-limit-lbl">위키 시각 보정</span>
            <button className="au-limit-save" onClick={runBackfill} disabled={backfilling}>
              <IconRefresh size={14} />{backfilling ? "보정 중…" : "기존 updated → 한국시간 초 단위 백필"}
            </button>
            {backfillNote && <span className="au-limit-note">{backfillNote}</span>}
          </div>
          <p className="set-note" style={{ marginTop: -2 }}>
            {backfillPending > 0 ? <>예전 페이지 <b>{fmt(backfillPending)}개</b>의 수정 시각이 날짜까지만 있습니다. </> : null}
            한 번 보정하면 <b>초 단위(KST)</b>로 채워지고 <b>이 버튼은 사라집니다</b>(1회성 · 새로 분석되는 페이지는 자동).
          </p>
        </>
      )}

      <div className="au-summary">
        <div className="au-sumcard"><span className="au-sumlabel">오늘 전체</span><span className="au-sumval">{fmt(todayTotal)} <em>토큰</em></span></div>
        <div className="au-sumcard"><span className="au-sumlabel">최근 7일 전체</span><span className="au-sumval">{fmt(weekTotal)} <em>토큰</em></span></div>
        <div className="au-sumcard"><span className="au-sumlabel">7일 내 사용자</span><span className="au-sumval">{activeUsers}<em>/{rows.length}명</em></span></div>
        <button className="au-refresh" onClick={load} disabled={loading} title="새로고침"><IconRefresh size={14} />{loading ? "불러오는 중…" : "새로고침"}</button>
      </div>

      <p className="set-note au-legend">
        ▮ 막대 = <b>오늘 토큰 사용량</b> — {dailyLimit > 0
          ? <>일일 상한(<b>{fmt(dailyLimit)}</b>) 대비 비율(80%↑ 주황·초과 빨강).</>
          : <>상한 미설정이라 <b>오늘 가장 많이 쓴 사용자(100%)</b> 대비 상대 비율(상대적 과사용 파악용).</>}
