      <div className="au-list">
        {rows.map((r) => {
          const overLimit = dailyLimit > 0 && r.todayTokens >= dailyLimit;
          const warn = dailyLimit > 0 && !overLimit && r.todayTokens >= dailyLimit * 0.8;
          const pct = dailyLimit > 0 ? Math.min(100, (r.todayTokens / dailyLimit) * 100) : (r.todayTokens / maxToday) * 100;
          const barColor = overLimit ? "var(--color-text-danger)" : warn ? "var(--color-text-warning)" : "var(--color-accent)";
          return (
            <div key={r.userId} className="au-item" style={!r.active ? { opacity: 0.55 } : undefined}>
              <div className="au-item-top">
