                    {r.role === "ADMIN" && <span className="au-badge"><IconShieldHalf size={11} />관리자</span>}
                    {!r.active && <span className="au-badge off">비활성</span>}
                  </span>
                  {r.email && <span className="au-email">{r.email}</span>}
                </span>
                <span className="au-stats">
                  <span className="au-today">오늘 <b>{fmt(r.todayTokens)}</b> 토큰 · {fmt(r.todayRequests)}건
                    {overLimit && <b className="au-over"> · 상한 초과</b>}{warn && <b className="au-warn"> · 임박</b>}</span>
                  <span className="au-week">7일 {fmt(r.weekTokens)} 토큰 · {fmt(r.weekRequests)}건</span>
                </span>
              </div>
              <div className="au-bar"><span className="au-fill" style={{ width: `${pct.toFixed(1)}%`, background: barColor }} /></div>
              {r.models.length > 0 ? (
                <div className="au-mtable">
                  <div className="au-mrow au-mhead">
                    <span className="au-m-name">모델</span>
                    <span className="au-m-num">오늘 토큰</span>
                    <span className="au-m-num">오늘 요청</span>
                    <span className="au-m-num">7일 토큰</span>
                    <span className="au-m-num">7일 요청</span>
                  </div>
                  {r.models.map((m) => (
                    <div key={m.model} className="au-mrow" title={m.model}>
                      <span className="au-m-name">{shortM(m.model)}</span>
                      <span className="au-m-num">{fmt(m.todayTokens)}</span>
                      <span className="au-m-num">{fmt(m.todayRequests)}</span>
                      <span className="au-m-num">{fmt(m.weekTokens)}</span>
                      <span className="au-m-num">{fmt(m.weekRequests)}</span>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="au-none">최근 7일 사용 없음</div>
              )}
            </div>
          );
        })}
      </div>
    </div></div>
  );
}

