    //   토큰 한도를 넘겨 잘린다 → 페이지마다 따로 전사(출력 한정)해 합친 뒤, 기존 텍스트 인제스트(L3b 응축)로 처리.
    const ocr = await transcribeScannedPages(raster.images, { model: opts.model ?? MODELS.ingest, provider, signal: opts.signal });
    if (ocr.text.trim()) {
      const dnote = raster.downscaled ? `(분석을 위해 페이지를 최대 ${raster.maxEdge}px로 다운스케일해 전사 — ★원본은 그대로 보존★)` : "(페이지 이미지에서 전사)";
