const bytes = source.byteSize ?? 0;
const rawAbs = wikiAbsPath(source.rawPath);
const assetsAbs = wikiAbsPath(`${source.rawPath.replace(/\.[^.]+$/, "")}.assets`);
try {
  // ★멱등★: 직전 실행이 파일 삭제·커밋까지 했으나 rawEvictedAt 설정 직전 끊긴 경우, 이 자료가 미리보기에
  //   다시 잡힌다(rawEvictedAt 여전히 null) → 재실행 시 파일은 이미 없음. 그때 ★빈 커밋★을 시도하면
  //   commitAll이 실패해 flag가 영영 안 박힌다 → ‘실제로 지울 게 있을 때만 커밋’ + flag는 항상 확정.
  let existed = false;
  try { await fs.access(rawAbs); existed = true; } catch { /* raw 이미 없음 */ }
  if (!existed) { try { await fs.access(assetsAbs); existed = true; } catch { /* assets도 없음 */ } }
  await withWikiWriteLock(async () => {
    try { await fs.unlink(rawAbs); } catch { /* 이미 없음 */ }
    try { await fs.rm(assetsAbs, { recursive: true, force: true }); } catch { /* 없음 */ }
    // ★normalized 사이드카는 보존★(재인제스트·검색 근거). 실제로 지운 게 있을 때만 커밋(빈 커밋 방지).
    if (existed) await commitAll(`retain-evict(${source.teamScope}): ${source.title} [원본 정리]`, { team: source.teamScope, gate: "RETENTION" });
  });
  // 파일이 (이미) 없든 방금 지웠든 ★rawEvictedAt를 확정★ → 멱등·자가치유(중복 후보 재등장 종결).
  await prisma.source.update({ where: { id }, data: { rawEvictedAt: new Date() } });
  evicted++; freedBytes += bytes;
} catch {
  skipped++;
}

