  let evicted = 0, freedBytes = 0, skipped = 0;
  for (const id of ids) {
    const source = await prisma.source.findUnique({ where: { id }, include: { ingestJobs: { where: { status: "APPLIED" }, take: 1 } } });
    // 안전 가드: 없거나·이미 정리됨·미분석(APPLIED 잡 없음)이면 ★건너뜀★(원본이 유일본인 자료 보호).
    if (!source || source.rawEvictedAt || source.ingestJobs.length === 0) { skipped++; continue; }
    const bytes = source.byteSize ?? 0;
    try {
      await withWikiWriteLock(async () => {
        try { await fs.unlink(wikiAbsPath(source.rawPath)); } catch { /* 이미 없음 */ }
        const stem = source.rawPath.replace(/\.[^.]+$/, "");
        try { await fs.rm(wikiAbsPath(`${stem}.assets`), { recursive: true, force: true }); } catch { /* 없음 */ }
        // ★normalized 사이드카는 보존★(재인제스트·검색 근거).
        await commitAll(`retain-evict(${source.teamScope}): ${source.title} [원본 정리]`, { team: source.teamScope, gate: "RETENTION" });
      });
      await prisma.source.update({ where: { id }, data: { rawEvictedAt: new Date() } });
      evicted++; freedBytes += bytes;
    } catch {
      skipped++;
    }
  }
  return { evicted, freedBytes, skipped };
}

