// ── L4 대용량 원본 보존정책 (docs/PLAN-large-files-and-chunking §11.6) ───────────────────
// L3가 "raw=불변 보존(저렴)" 가정을 깸(500MB 바이너리) → 오래된 대용량 원본 바이트를 정리한다.
// ★원본 바이트(raw/<sha>.<ext> + .assets)만 제거★ — 지식(위키 페이지)·정규화 사이드카(.normalized.md)·
//   Source 메타·git 이력은 ★보존★. 즉 검색·재질의는 그대로, 원본 다운로드만 불가해진다(rawEvictedAt 표시).
// ★자율 cron 삭제 금지★(cron 원칙) → 관리자 수동 트리거 + 미리보기. 기본 OFF(days<=0).
import { promises as fs } from "node:fs";
import { prisma } from "../db";
import { wikiAbsPath } from "../wiki/paths";
import { withWikiWriteLock, commitAll } from "../wiki/repo";

export interface RetentionConfig {
  days: number; // 이 일수보다 오래된 원본이 대상. <=0이면 ★비활성(아무것도 안 함)★.
  minBytes: number; // 이 크기 이상 원본만 대상(작은 raw는 저렴 → 유지).
}

// env 기반 기본 정책(관리자가 미리보기에서 override 가능). RETENTION_RAW_DAYS 미설정/0 = OFF.
export function retentionConfig(): RetentionConfig {
  return {
    days: Number(process.env.RETENTION_RAW_DAYS || 0), // 0 = ship-dark(비활성)
    minBytes: Number(process.env.RETENTION_RAW_MIN_MB || 25) * 1024 * 1024,
  };
}

export interface RawCandidate {
  id: number;
  createdAt: Date;
  byteSize: number | null;
  rawEvictedAt: Date | null;
  analyzed: boolean; // APPLIED 잡 있음(지식 추출됨) — ★UNANALYZED(raw가 유일본)는 false★
}

// ★순수★ 선택기 — 정리 대상 원본을 고른다(테스트 대상). days<=0이면 빈 배열(비활성).
//   조건: 미정리(rawEvictedAt null) ∧ 분석완료(analyzed) ∧ byteSize≥minBytes ∧ createdAt이 days일보다 오래됨.
export function selectEvictableRaw(items: RawCandidate[], opts: { days: number; minBytes: number; now: Date }): RawCandidate[] {
  if (opts.days <= 0) return []; // ship-dark
  const cutoff = opts.now.getTime() - opts.days * 86_400_000;
  return items.filter(
    (it) => it.rawEvictedAt == null && it.analyzed && (it.byteSize ?? 0) >= opts.minBytes && it.createdAt.getTime() <= cutoff,
  );
}

// 미리보기(읽기 전용) — 정책에 맞는 정리 후보 + 합계 용량. 관리자 UI가 보여주고 확인받는다.
export async function previewRawRetention(cfg: RetentionConfig, now: Date = new Date()): Promise<{ enabled: boolean; candidates: { id: number; title: string; scope: string; byteSize: number; createdAt: string }[]; totalBytes: number }> {
  if (cfg.days <= 0) return { enabled: false, candidates: [], totalBytes: 0 };
  // 분석완료(APPLIED 잡) ∧ 미정리 ∧ 크기 임계 후보를 DB에서 1차 추림 → 순수 선택기로 확정.
  const rows = await prisma.source.findMany({
    where: { rawEvictedAt: null, byteSize: { gte: cfg.minBytes }, ingestJobs: { some: { status: "APPLIED" } } },
    select: { id: true, title: true, teamScope: true, byteSize: true, createdAt: true },
    orderBy: { byteSize: "desc" },
    take: 500,
  });
  const cand = selectEvictableRaw(
    rows.map((r) => ({ id: r.id, createdAt: r.createdAt, byteSize: r.byteSize, rawEvictedAt: null, analyzed: true })),
    { days: cfg.days, minBytes: cfg.minBytes, now },
  );
  const ids = new Set(cand.map((c) => c.id));
  const picked = rows.filter((r) => ids.has(r.id));
  return {
    enabled: true,
    candidates: picked.map((r) => ({ id: r.id, title: r.title, scope: r.teamScope, byteSize: r.byteSize ?? 0, createdAt: r.createdAt.toISOString() })),
    totalBytes: picked.reduce((s, r) => s + (r.byteSize ?? 0), 0),
  };
}

// ★실제 정리★(관리자 확인한 id만) — 원본 바이트+.assets 제거, normalized·페이지·메타 보존, rawEvictedAt 표시.
//   단일 라이터(withWikiWriteLock) + 1커밋. UNANALYZED 등 안전 가드를 다시 확인(미리보기와 시점차 방어).
export async function evictRawForSources(ids: number[]): Promise<{ evicted: number; freedBytes: number; skipped: number }> {
  let evicted = 0, freedBytes = 0, skipped = 0;
  for (const id of ids) {
    const source = await prisma.source.findUnique({ where: { id }, include: { ingestJobs: { where: { status: "APPLIED" }, take: 1 } } });
    // 안전 가드: 없거나·이미 정리됨·미분석(APPLIED 잡 없음)이면 ★건너뜀★(원본이 유일본인 자료 보호).
    if (!source || source.rawEvictedAt || source.ingestJobs.length === 0) { skipped++; continue; }
    const bytes = source.byteSize ?? 0;
    try {
      await withWikiWriteLock(async () => {
        try { await fs.unlink(wikiAbsPath(source.rawPath)); } catch { /* 이미 없음 */ }
        const stem = source.rawPath.replace(/\.[^.]+$/, "");
        try { await fs.rm(wikiAbsPath(`${stem}.assets`), { recursive: true, force: true }); } catch { /* 없음 */ }
        // ★normalized 사이드카는 보존★(재인제스트·검색 근거).
        await commitAll(`retain-evict(${source.teamScope}): ${source.title} [원본 정리]`, { team: source.teamScope, gate: "RETENTION" });
      });
      await prisma.source.update({ where: { id }, data: { rawEvictedAt: new Date() } });
      evicted++; freedBytes += bytes;
    } catch {
      skipped++;
    }
  }
  return { evicted, freedBytes, skipped };
}

