    if (opts.signal?.aborted) throw e; // 사용자 취소는 그대로 전파(폴백으로 흡수 금지)
    // ★비전 미지원 공급자(Groq 등)거나 일시 오류★ → OCR 실패를 raw 에러로 노출하지 않고 아래 폴백으로:
    //   gemini/anthropic이면 native PDF 첨부, 아니면 '올바른 모델 안내'(정직한 친절 실패). (리뷰 #3)
    console.warn("[ingest] 스캔PDF 페이지 전사 실패 → 폴백:", String(e));
  }
}

