"use client";

// L4 대용량 원본 보존정책 관리자 콘솔(docs/PLAN-large-files-and-chunking §11.6).
//   ★자율 삭제 없음★ — 미리보기로 무엇이·얼마나 정리되는지 보고, 관리자가 확인한 자료만 정리한다.
//   정리는 ★원본 바이트만★(위키 페이지·추출본·메타·git 이력은 보존 → 검색·재질의 그대로, 원본 다운로드만 불가).
//   UI는 기존 관리자 콘솔(UsageConsole) 클래스·패턴 재사용(메모리 ui-follow-existing-design).
import { useEffect, useState } from "react";
import { IconDatabaseOff, IconRefresh, IconTrash } from "@tabler/icons-react";
import { confirmDialog } from "@/components/ui/Dialog";

interface Candidate { id: number; title: string; scope: string; byteSize: number; createdAt: string }
interface PreviewResp { config: { days: number; minMb: number }; enabled: boolean; candidates: Candidate[]; totalBytes: number; error?: string }

function fmtBytes(n: number): string {
  if (n >= 1024 * 1024 * 1024) return `${(n / 1024 / 1024 / 1024).toFixed(1)} GB`;
  if (n >= 1024 * 1024) return `${(n / 1024 / 1024).toFixed(1)} MB`;
  if (n >= 1024) return `${(n / 1024).toFixed(0)} KB`;
  return `${n} B`;
}
function fmtDate(iso: string): string {
  try { return new Date(iso).toLocaleDateString("ko-KR", { timeZone: "Asia/Seoul" }); } catch { return iso; }
}

export default function RetentionConsole(_props: { onClose?: () => void } = {}) {
  const [data, setData] = useState<PreviewResp | null>(null);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState<string | null>(null);
  const [selected, setSelected] = useState<Set<number>>(new Set());
  const [evicting, setEvicting] = useState(false);
  const [note, setNote] = useState("");

  async function load() {
    setLoading(true); setErr(null); setNote("");
    try {
      const r = await fetch("/api/admin/retention", { cache: "no-store" });
      const d = await r.json();
      if (!r.ok) throw new Error(d.error || "불러오기 실패");
      setData(d);
      setSelected(new Set((d.candidates || []).map((c: Candidate) => c.id))); // 기본 전체 선택(관리자가 빼면 제외)
    } catch (e) { setErr(e instanceof Error ? e.message : String(e)); }
    finally { setLoading(false); }
  }
  useEffect(() => { load(); }, []);

  function toggle(id: number) {
    setSelected((s) => { const n = new Set(s); if (n.has(id)) n.delete(id); else n.add(id); return n; });
  }

  const candidates = data?.candidates ?? [];
  const selectedBytes = candidates.filter((c) => selected.has(c.id)).reduce((s, c) => s + c.byteSize, 0);

  async function evict() {
    const ids = [...selected];
    if (!ids.length) { setNote("정리할 자료를 선택하세요."); return; }
    if (!await confirmDialog(
      `선택한 ${ids.length}개 자료의 ★원본 파일(${fmtBytes(selectedBytes)})★을 삭제합니다.\n` +
      `위키 페이지·추출본·메타·이력은 그대로 보존됩니다(원본 다운로드만 불가해짐).\n진행할까요?`,
    )) return;
    setEvicting(true); setNote("");
    try {
      const r = await fetch("/api/admin/retention", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ ids }) });
      const d = await r.json();
      if (!r.ok) throw new Error(d.error || "정리 실패");
      setNote(`정리됨 ${d.evicted}건 · ${fmtBytes(d.freedBytes)} 확보${d.skipped ? ` · 건너뜀 ${d.skipped}건` : ""} ✓`);
      load(); // 후보 목록 갱신(정리된 건 빠짐)
    } catch (e) { setNote(e instanceof Error ? e.message : String(e)); }
    finally { setEvicting(false); }
  }

  return (
    <div className="set-page"><div className="set-wrap">
      <h1 className="set-title"><IconDatabaseOff size={20} style={{ verticalAlign: "-3px", marginRight: 8 }} />원본 보존정책 (관리자)</h1>
      <p className="set-note" style={{ marginTop: -6 }}>
        오래·큰 <b>원본 파일</b>의 바이트만 정리해 저장공간을 확보합니다. <b>위키 지식·추출본·이력은 보존</b>되어
        검색·재질의는 그대로이고, 원본 다운로드만 불가해집니다(자료에 ‘원본 정리됨’ 표시). ★자율 삭제 없음 — 항상 여기서 확인 후 정리★.
      </p>

      {err && <div className="mat-banner err">{err}</div>}

      {data && !data.enabled && !err && (
        <div className="wt-empty">
          보존정책이 <b>비활성</b>입니다. 환경변수 <code>RETENTION_RAW_DAYS</code>(보존 일수)를 설정하면 켜집니다 —
          예: <code>180</code>이면 180일보다 오래된 <code>RETENTION_RAW_MIN_MB</code>(기본 25)MB 이상 ★분석 완료★ 원본이 정리 후보가 됩니다.
        </div>
      )}

      {data && data.enabled && (
        <>
          <div className="au-summary">
            <div className="au-sumcard"><span className="au-sumlabel">정책</span><span className="au-sumval">{data.config.days}<em>일↑ · {data.config.minMb}MB↑</em></span></div>
            <div className="au-sumcard"><span className="au-sumlabel">정리 후보</span><span className="au-sumval">{candidates.length}<em>건</em></span></div>
            <div className="au-sumcard"><span className="au-sumlabel">선택 용량</span><span className="au-sumval">{fmtBytes(selectedBytes)}</span></div>
            <button className="au-refresh" onClick={load} disabled={loading} title="새로고침"><IconRefresh size={14} />{loading ? "불러오는 중…" : "새로고침"}</button>
          </div>

          {note && <div className="mat-banner">{note}</div>}

          {candidates.length === 0 ? (
            <div className="wt-empty">{loading ? "불러오는 중…" : "정책에 해당하는 정리 후보가 없습니다."}</div>
          ) : (
            <>
              <div className="au-list">
                {candidates.map((c) => (
                  <label key={c.id} className="au-item" style={{ display: "flex", alignItems: "center", gap: 10, cursor: "pointer" }}>
                    <input type="checkbox" checked={selected.has(c.id)} onChange={() => toggle(c.id)} aria-label={`${c.title} 선택`} />
                    <span style={{ flex: 1, minWidth: 0 }}>
                      <span className="au-name" style={{ display: "block", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{c.title}</span>
                      <span className="au-email">{c.scope} · {fmtDate(c.createdAt)}</span>
                    </span>
                    <span className="au-today"><b>{fmtBytes(c.byteSize)}</b></span>
                  </label>
                ))}
              </div>
              <div className="au-limit" style={{ marginTop: 10 }}>
                <button className="au-limit-save" onClick={evict} disabled={evicting || selected.size === 0} style={{ background: "var(--color-text-danger)" }}>
                  <IconTrash size={14} />{evicting ? "정리 중…" : `선택 ${selected.size}건 원본 정리`}
                </button>
              </div>
            </>
          )}
        </>
      )}
    </div></div>
  );
}

