      const d = await r.json();
      if (!r.ok) throw new Error(d.error || "정리 실패");
      setNote(`정리됨 ${d.evicted}건 · ${fmtBytes(d.freedBytes)} 확보${d.skipped ? ` · 건너뜀 ${d.skipped}건` : ""} ✓`);
      load(); // 후보 목록 갱신(정리된 건 빠짐)
    } catch (e) { setNote(e instanceof Error ? e.message : String(e)); }
    finally { setEvicting(false); }
  }

  return (
    <div className="set-page"><div className="set-wrap">
      <h1 className="set-title"><IconDatabaseOff size={20} style={{ verticalAlign: "-3px", marginRight: 8 }} />원본 보존정책 (관리자)</h1>
      <p className="set-note" style={{ marginTop: -6 }}>
        오래·큰 <b>원본 파일</b>의 바이트만 정리해 저장공간을 확보합니다. <b>위키 지식·추출본·이력은 보존</b>되어
        검색·재질의는 그대로이고, 원본 다운로드만 불가해집니다(자료에 ‘원본 정리됨’ 표시). ★자율 삭제 없음 — 항상 여기서 확인 후 정리★.
      </p>

      {err && <div className="mat-banner err">{err}</div>}

      {data && !data.enabled && !err && (
        <div className="wt-empty">
          보존정책이 <b>비활성</b>입니다. 환경변수 <code>RETENTION_RAW_DAYS</code>(보존 일수)를 설정하면 켜집니다 —
          예: <code>180</code>이면 180일보다 오래된 <code>RETENTION_RAW_MIN_MB</code>(기본 25)MB 이상 ★분석 완료★ 원본이 정리 후보가 됩니다.
        </div>
      )}

      {data && data.enabled && (
        <>
          <div className="au-summary">
            <div className="au-sumcard"><span className="au-sumlabel">정책</span><span className="au-sumval">{data.config.days}<em>일↑ · {data.config.minMb}MB↑</em></span></div>
            <div className="au-sumcard"><span className="au-sumlabel">정리 후보</span><span className="au-sumval">{candidates.length}<em>건</em></span></div>
            <div className="au-sumcard"><span className="au-sumlabel">선택 용량</span><span className="au-sumval">{fmtBytes(selectedBytes)}</span></div>
            <button className="au-refresh" onClick={load} disabled={loading} title="새로고침"><IconRefresh size={14} />{loading ? "불러오는 중…" : "새로고침"}</button>
          </div>

          {note && <div className="mat-banner">{note}</div>}

          {candidates.length === 0 ? (
            <div className="wt-empty">{loading ? "불러오는 중…" : "정책에 해당하는 정리 후보가 없습니다."}</div>
          ) : (
            <>
              <div className="au-list">
                {candidates.map((c) => (
                  <label key={c.id} className="au-item" style={{ display: "flex", alignItems: "center", gap: 10, cursor: "pointer" }}>
                    <input type="checkbox" checked={selected.has(c.id)} onChange={() => toggle(c.id)} aria-label={`${c.title} 선택`} />
                    <span style={{ flex: 1, minWidth: 0 }}>
                      <span className="au-name" style={{ display: "block", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{c.title}</span>
                      <span className="au-email">{c.scope} · {fmtDate(c.createdAt)}</span>
                    </span>
                    <span className="au-today"><b>{fmtBytes(c.byteSize)}</b></span>
                  </label>
                ))}
              </div>
              <div className="au-limit" style={{ marginTop: 10 }}>
                <button className="au-limit-save" onClick={evict} disabled={evicting || selected.size === 0} style={{ background: "var(--color-text-danger)" }}>
                  <IconTrash size={14} />{evicting ? "정리 중…" : `선택 ${selected.size}건 원본 정리`}
                </button>
              </div>
            </>
          )}
        </>
      )}
    </div></div>
  );
}

