99	  filename: string,
100	  mime: string,
101	  opts?: { diarize?: boolean },
102	): Promise<ExtractResult> {
103	  const groq = openaiCompatEnabled();
104	  const gem = geminiEnabled();
105	  if (!groq && !gem) {
