159	//   (이 파일은 convert.ts→node:child_process를 끌어 클라 번들에 못 들어가므로, 순수 함수는 ./transcript에 둔다.)
160	export { isTranscribedExtractor } from "./transcript";
161	
162	/** 진단·라벨용 현행 1순위 전사 모델명. */
163	export function sttModelLabel(): string {
164	  return openaiCompatEnabled() ? `groq-${groqSttModel()}` : "gemini";
165	}
