import type { ExtractResult } from "./extract";
import { groqTranscribe, openaiCompatEnabled, groqSttModel, GROQ_STT_MAX_BYTES, type TranscribeResult } from "./openai-compat";
import { geminiTranscribe, geminiEnabled } from "./gemini";
import { ffmpegAvailable, extractAudioMp3, splitAudioMp3 } from "./convert";

// 긴 음성 청크 전사(L1) — Groq 25MB 한도를 ffmpeg 분할로 우회. 10분 청크(16kHz mono 64k ≈ 4.8MB), 제한 병렬.
const STT_CHUNK_SEC = 600;
const STT_CHUNK_CONCURRENCY = 3;

/** 청크 전사 결과들을 순서대로 이어붙임(L1). 텍스트는 빈 줄로 결합, duration 합산. 순수(테스트용). */
export function stitchTranscripts(parts: { text: string; durationSec?: number }[]): { text: string; durationSec?: number } {
  const text = parts.map((p) => (p.text || "").trim()).filter(Boolean).join("\n\n");
  const dur = parts.reduce((s, p) => s + (p.durationSec ?? 0), 0);
  return { text, durationSec: dur > 0 ? dur : undefined };
}

/** 큰 오디오를 ffmpeg로 분할해 청크별 Groq 전사 후 이어붙임. 분할/전부 실패면 null(폴백). 일부 실패는 부분 보존. */
async function groqTranscribeChunked(buf: Buffer, filename: string): Promise<TranscribeResult | null> {
  const split = await splitAudioMp3(buf, STT_CHUNK_SEC);
  if (!split || !split.length) return null;
  const chunks: Buffer[] = split; // 비-null 확정(클로저 안에서도 narrowing 유지)
  const base = filename.replace(/\.[^.]+$/, "");
  const results: (TranscribeResult | null)[] = new Array(chunks.length).fill(null);
  let next = 0;
  async function worker() {
    while (next < chunks.length) {
      const i = next++;
      try { results[i] = await groqTranscribe(chunks[i], `${base}.part${String(i).padStart(4, "0")}.mp3`, "audio/mpeg"); }
      catch (e) { console.warn(`[stt] 청크 ${i + 1}/${chunks.length} 전사 실패: ${String(e)}`); results[i] = null; }
    }
  }
  await Promise.all(Array.from({ length: Math.min(STT_CHUNK_CONCURRENCY, chunks.length) }, worker));
  const ok = results.filter((r): r is TranscribeResult => !!r); // 순서 유지(인덱스 순)
  if (!ok.length) return null;
  const s = stitchTranscripts(ok);
  return { text: s.text, durationSec: s.durationSec, model: ok[0].model };
}

// ffmpeg 선행이 필요한 컨테이너 — Groq가 직접 못 받는 영상(.mov 등). FFMPEG_CMD 설정 시에만 처리(5c).
//   (STT_EXTS=Groq 직수 컨테이너는 extract.ts. 여기 set은 업로드 게이팅·dispatch가 import.)
export const STT_FFMPEG_EXTS = ["mov", "mkv", "avi", "m4v", "wmv", "flv"];

function extLower(name: string): string {
  return (name || "").toLowerCase().match(/\.([a-z0-9]+)$/)?.[1] ?? "";
}

// 음성·영상 전사(STT) 오케스트레이션 — 추출 레이어(lib/extract.ts)의 한 추출기.
// 전사문을 정규화 markdown(ExtractResult.text)으로 돌려주면, 그 뒤는 기존 ingestText가 처리한다.
// 설계: docs/PLAN-audio-video-ingest.md.
//   5a = Groq 기본. 5b = Groq 실패(429·오류) 시 Gemini 폴백(★Gemini는 외부 전송+무료=학습 → UI 경고는 extractor가
//        'gemini-'로 시작하는지로 판별·표시). ★전사 모델 ≠ 분석 모델: 여기 텍스트는 .txt와 동일 취급 → 분석은 별도 선택.

// Gemini STT 폴백 허용 여부(기본 on). ★외부학습 차단 정책★이면 STT_GEMINI_FALLBACK=false로 끈다(docs §E).
export function sttGeminiFallback(): boolean {
  return process.env.STT_GEMINI_FALLBACK !== "false";
}
// 전사 공급자 한도(429) 오류 판별(순수) — 한도는 일시적이라 폴백보다 '재처리'가 정답.
export function isRateLimitError(msg: string): boolean {
  return /\b429\b|rate limit|한도 초과|RESOURCE_EXHAUSTED|quota/i.test(msg);
}

/** 초 → "m:ss"(헤더 표기용). 없거나 비정상이면 빈 문자열. */
export function fmtDuration(sec?: number): string {
  if (!sec || !Number.isFinite(sec) || sec < 0) return "";
  const m = Math.floor(sec / 60);
  const s = Math.floor(sec % 60);
  return `${m}:${String(s).padStart(2, "0")}`;
}

/**
 * 전사 텍스트 → 정규화 ExtractResult. 네트워크 없음(순수) — 테스트·재사용 가능.
 * quality는 전사문 글자수 기준(기존 extract 패턴). extractor는 공급자 포함 전체 라벨(예: groq-... / gemini-...).
 */
export function buildTranscriptResult(
  text: string,
  filename: string,
  durationSec: number | undefined,
  extractor: string,
): ExtractResult {
  const clean = (text || "").trim();
  const len = clean.replace(/\s/g, "").length;
  const dur = fmtDuration(durationSec);
  const header = `## 음성 텍스트 변환 (${filename}${dur ? `, ${dur}` : ""})`;
  return {
    text: clean ? `${header}\n\n${clean}` : "",
    quality: len >= 40 ? "full" : len > 0 ? "partial" : "none",
    extractor,
    meta: { durationSec, transcribed: true },
  };
}

/**
 * 오디오/영상 버퍼 → 전사 ExtractResult. ★Groq 기본 → Gemini 폴백★.
 * - 둘 다 키 없으면 quality:'none'(graceful 미분석 — 호출측 dispatch가 흡수).
 * - Groq 실패(429·오류)면 Gemini로 폴백(가능할 때). 전사 오류는 throw → dispatch try/catch가 'none'+error로 흡수.
 */
export async function transcribe(
  buf: Buffer,
  filename: string,
  mime: string,
  opts?: { diarize?: boolean },
): Promise<ExtractResult> {
  const groq = openaiCompatEnabled();
  const gem = geminiEnabled();
  if (!groq && !gem) {
    // 전사 공급자 미설정 → 원본은 보존되고 '미분석'으로 남는다(4j 패턴).
    return { text: "", quality: "none", extractor: "stt-unconfigured" };
  }
  // 영상(.mov 등)·대용량(>25MB)은 ffmpeg로 오디오만 추출해 한도·비용 회피(5c). 미설정/실패 시 원본 그대로 시도.
  const a = await prepareAudio(buf, filename, mime);
  // ★화자 구분(diarize) 요청 → Gemini 전용★(Groq Whisper는 화자분리 미지원). Gemini 없으면 아래 일반 경로(Groq 평문, 구분 없음).
  if (opts?.diarize && gem) {
    const g = await geminiTranscribe(a.buf, a.filename, a.mime, { diarize: true });
    return buildTranscriptResult(g.text, filename, g.durationSec, `gemini-${g.model}`);
  }
  // 1순위: Groq(무료·초고속). ★25MB 초과 + ffmpeg 있으면 청크 분할 전사(L1)★.
  if (groq) {
    const chunked = a.buf.byteLength > GROQ_STT_MAX_BYTES && ffmpegAvailable();
    try {
      const r = chunked ? await groqTranscribeChunked(a.buf, a.filename) : await groqTranscribe(a.buf, a.filename, a.mime);
      if (r) return buildTranscriptResult(r.text, filename, r.durationSec, `groq-${r.model}${chunked ? "-chunked" : ""}`);
      console.warn("[stt] Groq 청크 전사가 결과를 못 냄 → 폴백 시도"); // r=null(분할/전부 실패)
    } catch (e) {
      const msg = String(e);
      // ★Groq 한도(429)는 일시적★ — Gemini 폴백은 긴 음성에서 잘림·환각으로 ★쓰레기 전사★를 만든다(실측).
      //   폴백하지 말고 명확히 실패시켜 '잠시 후 재처리'를 유도(Groq 한도는 수~십분 내 리셋). (docs §E)
      if (isRateLimitError(msg)) {
        throw new Error("음성 텍스트 변환 한도(Groq 무료 등급, 시간당 약 2시간)를 초과했습니다. 잠시 후(약 10분) [재처리]하면 정상 변환됩니다. 급하면 음성을 더 짧게 잘라 올려주세요.");
      }
      if (!gem || !sttGeminiFallback()) throw e; // 폴백 없음/비활성(STT_GEMINI_FALLBACK=false) → 그대로 전파
      console.warn(`[stt] Groq 전사 실패 → Gemini 폴백: ${msg}`);
    }
    if (!gem || !sttGeminiFallback()) return { text: "", quality: "none", extractor: "stt-failed" }; // Groq뿐/폴백 비활성 → 미분석 보존
  }
  // 폴백(또는 Groq 미설정·Gemini만): Gemini. ★외부 전송+무료=학습 → extractor 'gemini-'로 UI 경고 판별.
  const g = await geminiTranscribe(a.buf, a.filename, a.mime);
  return buildTranscriptResult(g.text, filename, g.durationSec, `gemini-${g.model}`);
}

/** 영상/대용량이면 ffmpeg로 오디오(mp3)만 추출. ffmpeg 미설정/실패면 원본을 그대로 반환(graceful). */
async function prepareAudio(buf: Buffer, filename: string, mime: string): Promise<{ buf: Buffer; filename: string; mime: string }> {
  const ext = extLower(filename);
  const needFfmpeg = STT_FFMPEG_EXTS.includes(ext) || mime.startsWith("video/") || buf.byteLength > GROQ_STT_MAX_BYTES;
  if (needFfmpeg && ffmpegAvailable()) {
    const audio = await extractAudioMp3(buf, ext || "bin");
    if (audio && audio.byteLength > 0) {
      return { buf: audio, filename: filename.replace(/\.[^.]+$/, "") + ".mp3", mime: "audio/mpeg" };
    }
  }
  return { buf, filename, mime };
}

/** 현재 STT(전사) 사용 가능 여부 — uploadPolicy 게이팅용. Groq 또는 Gemini 키. */
export function sttAvailable(): boolean {
  return openaiCompatEnabled() || geminiEnabled();
}

// 전사 소스 판별은 ★클라이언트 공용★이라 순수 모듈로 분리해 re-export(서버 import `from "./stt"`는 그대로 동작).
//   (이 파일은 convert.ts→node:child_process를 끌어 클라 번들에 못 들어가므로, 순수 함수는 ./transcript에 둔다.)
export { isTranscribedExtractor } from "./transcript";

/** 진단·라벨용 현행 1순위 전사 모델명. */
export function sttModelLabel(): string {
  return openaiCompatEnabled() ? `groq-${groqSttModel()}` : "gemini";
}

