// ★전사 품질 가드(§F)★: 환각 반복 루프를 1주기로 접어 garbage가 분석에 들어가지 않게 한다(앞부분 정상 보존).
//   루프 없으면 clean===raw(불변·회귀0). 접혔으면 meta.loopCollapsed로 UI 배지/검토 신호.
const { text: clean, info: loop } = collapseTranscriptLoops(raw);
const len = clean.replace(/\s/g, "").length;
const dur = fmtDuration(durationSec);
const header = `## 음성 텍스트 변환 (${filename}${dur ? `, ${dur}` : ""})`;
return {
  text: clean ? `${header}\n\n${clean}` : "",
  // 루프를 많이 접었으면(주로 환각) full이라도 ★partial로 낮춰★ 검토를 거치게 한다(자동승인 방지).
  quality: len >= 40 ? (loop.collapsed && loop.removed >= 8 ? "partial" : "full") : len > 0 ? "partial" : "none",
  extractor,
  meta: { durationSec, transcribed: true, ...(loop.collapsed ? { loopCollapsed: loop.removed, loopPhrase: loop.phrase } : {}) },
};

