// 전사(STT) 관련 ★클라이언트·서버 공용★ 순수 헬퍼 — 서버 전용 의존(child_process 등) 없이 클라 번들에 안전.
// (lib/stt.ts는 convert.ts→node:child_process를 끌고 와 클라 컴포넌트에서 import 불가 → 순수 판별만 여기로 분리.)

/**
 * extractor가 음성·영상 전사(groq-/gemini-)인지 — 모델 자동추천에서 byteSize 크기 휴리스틱을 건너뛰거나
 * (전사 소스 byteSize는 '오디오 바이트'라 텍스트 길이가 아님) UI에서 음성 소스를 식별하는 데 쓴다.
 */
export function isTranscribedExtractor(extractor: string | null | undefined): boolean {
  return /^(groq|gemini)-/.test(extractor ?? "");
}

// ── 전사 품질 가드: 환각 반복 루프 감지·정리 (PLAN-multi-upload §F) ──────────────────────
// 증상(실측): Gemini가 대용량 음성을 청크 없이 inline 전사하다 후반부에 짧은 구절을 무한 반복
//   ("아, 그래. 아, 안 줬어."×N) → 그 쓰레기가 normalized 텍스트로 저장돼 분석에 투입됨.
// 대책: 연속(또는 주기 A·B·A·B) 반복을 ★1주기로 접어★ garbage를 분석에서 제거하되 ★앞부분(정상)은 보존★.
//   ★루프가 없으면 입력 텍스트를 100% 그대로 반환★(회귀 0). 순수 함수 — 클라/서버 공용·테스트 용이.

export interface TranscriptLoopInfo {
  collapsed: boolean; // 한 번이라도 접었나
  removed: number;    // 생략된 구절(clause) 수
  phrase?: string;    // 대표 반복 구절(가장 많이 생략된 것)
}

// 비교용 정규화 — 공백·문장부호 제거 + 소문자(반복 판정은 내용 동일성만 본다).
function normClause(s: string): string {
  return s.replace(/[\s.!?。…,'"·~\-—()[\]]/g, "").toLowerCase();
}

/**
 * 전사 텍스트의 ★반복 루프★(연속 동일 구절 또는 주기적 A·B 반복)를 1주기로 접는다.
 * - 구절 경계(문장부호·줄바꿈)로 나눠, 길이 1~4 주기가 minRepeats회 이상 연속 반복되면 1주기만 남기고 생략 표시.
 * - ★짧은 구절만★ 대상(maxUnitLen) — 정당하게 반복되는 긴 문단은 건드리지 않는다.
 * - 반복이 없으면 입력을 ★그대로★ 반환(text 동일·collapsed=false). 분리는 lookbehind라 미접촉부 원문 보존.
 */
export function collapseTranscriptLoops(
  text: string,
  opts?: { minRepeats?: number; maxCycleLen?: number; maxUnitLen?: number },
): { text: string; info: TranscriptLoopInfo } {
  const minRepeats = opts?.minRepeats ?? 4; // 같은 구절이 4회 이상 반복돼야 루프로 본다(정상 반복 보호)
  const maxCycleLen = opts?.maxCycleLen ?? 4; // 주기 최대 4구절(A·B·C·D 반복까지)
  const maxUnitLen = opts?.maxUnitLen ?? 60; // 한 구절 정규화 길이 상한 — 긴 문단 반복은 정상으로 본다
  if (!text) return { text, info: { collapsed: false, removed: 0 } };

  // 구절 분리: 문장부호/줄바꿈 ★뒤에서★ 자른다(lookbehind) → 각 조각이 구분자를 보유 → 단순 concat이 원문 복원.
  const pieces = text.split(/(?<=[.!?。…\n])/);
  if (pieces.length < minRepeats) return { text, info: { collapsed: false, removed: 0 } };
  const norm = pieces.map(normClause);

  const out: string[] = [];
  const removedByPhrase = new Map<string, number>();
  let removed = 0;
  let i = 0;
  while (i < pieces.length) {
    let didCollapse = false;
    // 더 긴 주기부터 시도(최대 압축). 주기 L이 minRepeats회 이상 연속 반복되는지 본다.
    for (let L = Math.min(maxCycleLen, Math.floor((pieces.length - i) / minRepeats)); L >= 1; L--) {
      // 주기 블록의 정규화가 모두 비었으면(구분자만) 스킵, 길이 상한 위반도 스킵.
      const block = norm.slice(i, i + L);
      if (block.some((b) => b.length === 0) || block.some((b) => b.length > maxUnitLen)) continue;
      let reps = 1;
      while (i + (reps + 1) * L <= pieces.length) {
        let same = true;
        for (let k = 0; k < L; k++) { if (norm[i + reps * L + k] !== block[k]) { same = false; break; } }
        if (!same) break;
        reps++;
      }
      if (reps >= minRepeats) {
        for (let k = 0; k < L; k++) out.push(pieces[i + k]); // 1주기만 보존
        const omitted = (reps - 1) * L;
        removed += omitted;
        const phrase = pieces.slice(i, i + L).join("").trim().slice(0, 40);
        removedByPhrase.set(phrase, (removedByPhrase.get(phrase) ?? 0) + omitted);
        out.push(`\n[⚠ 전사 품질: 같은 구절이 ${reps}회 반복되어 전사 환각으로 판단, ${reps - 1}회 생략함]\n`);
        i += reps * L;
        didCollapse = true;
        break;
      }
    }
    if (!didCollapse) { out.push(pieces[i]); i++; }
  }

  if (removed === 0) return { text, info: { collapsed: false, removed: 0 } }; // ★불변: 루프 없으면 원문 그대로★
  const phrase = [...removedByPhrase.entries()].sort((a, b) => b[1] - a[1])[0]?.[0];
  return { text: out.join(""), info: { collapsed: true, removed, phrase } };
}

