import { promises as fs } from "node:fs";
import path from "node:path";
import { wikiAbsPath, assertInScope } from "./paths";
import { atomicWriteFile } from "./atomicWrite";
import { kstStamp, kstDateStr, kstTimeStr } from "../time";

export interface WikiEdit {
  op: "create" | "append";
  path: string; // scope 포함 상대경로 (예: common/entities/결제-게이트웨이.md)
  content: string;
}

export interface EditSet {
  edits: WikiEdit[];
  log_entry: string;
  confidence: number;
  needs_human?: boolean;
}

// 편집셋이 ★위키에 반영할 실제 페이지 편집★을 담고 있는지(순수). 빈 edits(또는 내용 없는 op)면 적용해도
//   페이지가 안 생긴다 → "반영됨/페이지로 가기"로 표시하면 끊긴 링크(404)다. ★정직한 실패★ 판단에 쓴다.
export function hasContentEdits(editSet: { edits?: WikiEdit[] } | null | undefined): boolean {
  return !!editSet?.edits?.some(
    (e) => (e.op === "create" || e.op === "append") && !!e.path && (e.content ?? "").trim().length > 0,
  );
}

