import { promises as fs } from "node:fs";
import path from "node:path";
import { wikiAbsPath, assertInScope } from "./paths";
import { atomicWriteFile } from "./atomicWrite";
import { kstStamp, kstDateStr, kstTimeStr } from "../time";

export interface WikiEdit {
  op: "create" | "append";
  path: string; // scope 포함 상대경로 (예: common/entities/결제-게이트웨이.md)
  content: string;
}

export interface EditSet {
  edits: WikiEdit[];
  log_entry: string;
  confidence: number;
  needs_human?: boolean;
}

// 편집셋이 ★위키에 반영할 실제 페이지 편집★을 담고 있는지(순수). 빈 edits(또는 내용 없는 op)면 적용해도
//   페이지가 안 생긴다 → "반영됨/페이지로 가기"로 표시하면 끊긴 링크(404)다. ★정직한 실패★ 판단에 쓴다.
export function hasContentEdits(editSet: { edits?: WikiEdit[] } | null | undefined): boolean {
  return !!editSet?.edits?.some(
    (e) => (e.op === "create" || e.op === "append") && !!e.path && (e.content ?? "").trim().length > 0,
  );
}

// 초 단위까지(YYYY-MM-DD HH:mm:ss, UTC) — 변경로그·frontmatter updated의 '추가/업데이트 시간'을 일자만이 아니라 시각까지 기록.
function stampFull(): string {
  return kstStamp(); // 한국 시간(KST) — 변경로그·frontmatter updated 공용
}
// 본문 frontmatter의 updated를 ★적용 시각(초)★으로 정규화 — LLM이 날짜만 적어도 위키 리더에서 초까지 보이게.
function normalizeUpdated(content: string): string {
  if (!content.startsWith("---\n")) return content;
  const close = content.indexOf("\n---", 4);
  if (close === -1) return content;
  const head = content.slice(0, close);
  const tail = content.slice(close);
  const re = /(\n\s*updated\s*:)[^\n]*/;
  return re.test(head) ? head.replace(re, `$1 ${stampFull()}`) + tail : content;
}

/**
 * 모델이 낸 경로를 scope 안으로 보정한다(약한 로컬 모델이 'common/' 접두사를 빠뜨리는 경우 구제).
 * 선행 '/'·'./'·'wiki/' 제거 후, scope 접두사가 없으면 붙인다. ★보정 후에도 assertInScope가
 * '..'·'.'·빈 세그먼트를 막으므로 ACL/경로탈출 보장은 유지된다(보정이 scope를 못 벗어남).
 */
export function coercePath(scope: string, p: string): string {
  let s = String(p ?? "").trim().replace(/\\/g, "/").replace(/^\.?\/+/, "").replace(/^wiki\//, "");
  if (s !== scope && !s.startsWith(scope + "/")) s = `${scope}/${s}`;
  return s;
}

/**
 * 편집셋을 런타임 위키 작업트리에 적용한다. 변경된 상대경로 목록을 반환.
 * 커밋은 호출자가 withWikiWriteLock 임계구역 안에서 수행한다(단일 라이터).
 * - create: 파일 전체를 쓴다(LLM이 기존 본문을 병합한 전체 내용을 보냈다는 전제).
 * - append: 기존 파일 뒤에 섹션을 덧붙인다.
 * - log.md(append-only 이력)는 LLM이 아니라 코드가 log_entry로 누적한다.
 */
export async function applyEditSet(scope: string, editSet: EditSet): Promise<string[]> {
  const changed: string[] = [];
  let applied = 0;
  const skipped: string[] = [];

  for (const edit of editSet.edits) {
    // 무효 op·scope 밖 경로는 '그 편집만' 건너뛴다(약한 모델의 실수로 전체 인제스트가 죽지 않도록).
    // ★scope 밖 경로는 절대 쓰지 않으므로 ACL 보장은 유지된다(건너뛰기=미적용).
    if (edit.op !== "create" && edit.op !== "append") { skipped.push(`op:${edit.op}`); continue; }
    const epath = coercePath(scope, edit.path); // scope 접두사 보정(약한 모델 구제)
    try {
      assertInScope(scope, epath); // 보정 후에도 scope 밖/상위참조면 throw → 이 edit만 skip
    } catch {
      skipped.push(edit.path);
      continue;
    }
    const abs = wikiAbsPath(epath);
    await fs.mkdir(path.dirname(abs), { recursive: true });

    if (edit.op === "append") {
      let prev = "";
      try {
        prev = await fs.readFile(abs, "utf8");
      } catch {
        /* 없으면 새로 생성 */
      }
      const sep = !prev ? "" : prev.endsWith("\n") ? "\n" : "\n\n";
      await atomicWriteFile(abs, prev + sep + edit.content); // 원자적(읽기 파드 보호)
    } else {
      await atomicWriteFile(abs, normalizeUpdated(edit.content));
    }
    changed.push(epath);
    applied++;
  }

  if (skipped.length) console.warn(`[applyEditSet] scope=${scope} 건너뜀(${skipped.length}): ${skipped.join(", ")}`);
  // 편집이 있었는데 하나도 유효하지 않으면(전부 scope 밖/무효) 명확히 실패시킨다(빈 커밋 방지).
  if (editSet.edits.length > 0 && applied === 0) {
    throw new Error(`유효한 편집이 없습니다(경로가 모두 scope '${scope}/' 밖이거나 무효). 모델이 위키 경로 규칙을 못 따랐습니다.`);
  }

  // 이력 누적 (append-only, ★날짜별 그룹★: 날짜가 바뀌면 '## YYYY-MM-DD' 헤더를 새로 연다)
  if (editSet.log_entry) {
    const logRel = `${scope}/log.md`;
    const logAbs = wikiAbsPath(logRel);
    let prev = "";
    try {
      prev = await fs.readFile(logAbs, "utf8");
    } catch {
      /* 없으면 새로 생성 */
    }
    const today = kstDateStr();   // YYYY-MM-DD (KST)
    const time = kstTimeStr();    // HH:mm:ss (KST)
    // 마지막 날짜 헤더가 오늘과 다르면(또는 없으면) 새 날짜 그룹을 연다.
    const dh = [...prev.matchAll(/^##\s+(\d{4}-\d{2}-\d{2})\s*$/gm)];
    const needHeader = !dh.length || dh[dh.length - 1][1] !== today;
    const base = prev && !prev.endsWith("\n") ? prev + "\n" : prev;
    const headerBlock = needHeader ? `${base && !base.endsWith("\n\n") ? "\n" : ""}## ${today}\n` : "";
    await atomicWriteFile(logAbs, base + headerBlock + `- ${time} ${editSet.log_entry}\n`);
    changed.push(logRel);
  }

  return changed;
}

