{!archivedMode && (
  <span className={`mat-status ${s.status === "APPLIED" ? (isRaw ? "muted" : "ok") : s.status === "FAILED" ? "err" : s.status === "UNANALYZED" ? "warn" : s.status === "PENDING" || s.status === "RUNNING" || s.status === "APPLYING" || s.status === "QUEUED" ? "pend" : "muted"}`}>
    {isCanceling ? "취소 중…" : busy ? "처리 중…" : s.status === "APPLIED" ? (isRaw ? "원본 보관" : "반영됨") : s.status === "FAILED" ? "실패" : s.status === "SKIPPED_DUP" ? "중복" : s.status === "UNANALYZED" ? "미분석" : s.status === "QUEUED" ? "대기 중" : s.status === "PENDING" ? "분석 대기" : s.status === "RUNNING" ? "분석 중…" : s.status === "APPLYING" ? "반영 중…" : s.status === "NEEDS_REVIEW" ? "검토 대기" : s.status ?? "-"}
  </span>
)}
{/* 액션은 ★아이콘만★(고정폭) — 상태 배지·아이콘 열 정렬 유지. '재처리'·'AI로 분석'은 아래 별도 줄로 뺀다. */}
<div className="mat-acts">
  {/* L4: 원본 정리됨이면 열기 비활성(지식·추출본은 유지). */}
  {s.rawEvicted
    ? <span className="mat-act" style={{ opacity: 0.4, cursor: "default" }} title="원본은 보존정책에 따라 정리됨(분석본·위키 지식은 유지)"><IconExternalLink size={13} /></span>
    : <a className="mat-act" href={`/api/materials/${s.id}/raw`} target="_blank" rel="noreferrer" title="원본 열기"><IconExternalLink size={13} /></a>}
  {archivedMode ? (
    <>
      <button className="mat-act" disabled={busy} onClick={() => onRestore!(s)} title="복원"><IconArrowBackUp size={14} /></button>
      <button className="mat-del" disabled={deleting === s.id || busy} onClick={() => onPurge!(s)} title="영구삭제"><IconTrashX size={14} /></button>
    </>
  ) : (
    <>
      {!stuck && <button className="mat-act" onClick={() => onWiki(s)} title="위키 페이지로 이동"><IconArrowUpRight size={13} /></button>}
      {s.hasExtracted && (
        <a className="mat-act" href={`/api/materials/${s.id}/extracted`} target="_blank" rel="noreferrer" title="추출본(읽은 텍스트)"><IconArticle size={13} /></a>
      )}
      {canManage && <button className="mat-del" disabled={deleting === s.id || busy} onClick={() => onArchive(s)} title="아카이브(삭제)"><IconTrash size={13} /></button>}
    </>

