import { describe, it, expect } from "vitest";
import { hasContentEdits } from "../lib/wiki/applyEditSet";

// ★정직한 실패★ 판단(lib/wiki/applyEditSet.hasContentEdits).
//   배경: 모델이 자료를 못 읽으면 빈 편집셋(edits:[])을 낸다. 이걸 승인하면 페이지가 안 생기는데도
//   "반영됨 + 페이지로 가기"가 떠 끊긴 링크(404)가 됐다(스캔 PDF를 codex로 분석 시 재현).
//   → 적용 전에 "반영할 실제 편집이 있는가"를 가려 가짜 성공 대신 실패로 표시한다.
describe("hasContentEdits (빈 편집셋 = 정직한 실패)", () => {
  it("유효한 create/append 편집이 있으면 true", () => {
    expect(hasContentEdits({ edits: [{ op: "create", path: "common/topics/a.md", content: "본문" }] })).toBe(true);
    expect(hasContentEdits({ edits: [{ op: "append", path: "common/entities/b.md", content: "추가" }] })).toBe(true);
  });
  it("빈 edits면 false (가짜 성공 차단)", () => {
    expect(hasContentEdits({ edits: [] })).toBe(false);
  });
  it("null/undefined/누락도 안전하게 false", () => {
    expect(hasContentEdits(null)).toBe(false);
    expect(hasContentEdits(undefined)).toBe(false);
    expect(hasContentEdits({})).toBe(false);
  });
  it("op은 있으나 path·content가 비면 false (내용 없는 껍데기 op 방어)", () => {
    expect(hasContentEdits({ edits: [{ op: "create", path: "common/topics/a.md", content: "   " }] })).toBe(false);
    expect(hasContentEdits({ edits: [{ op: "create", path: "", content: "본문" }] })).toBe(false);
  });
  it("알 수 없는 op은 무시 — 유효 op이 하나도 없으면 false", () => {
    // @ts-expect-error 런타임 방어 검증(타입 밖 op)
    expect(hasContentEdits({ edits: [{ op: "delete", path: "common/topics/a.md", content: "x" }] })).toBe(false);
  });
});

