// generateContent의 inline(base64) 요청 총량 한도(~20MB)를 넘는 대용량 첨부는 Files API에 먼저 업로드해
//   fileUri로 참조한다. 그 ★경계 판정★을 순수 함수로 단일화(테스트·재사용) — gemini.ts가 이걸 호출한다.
// ★메모리 최적화(파일경로 스트리밍)는 별도★: 본 함수는 '어느 경로냐'만 정하고, 실제 업로드 바디를
//   base64 대신 파일 스트림으로 보내는 건 uploadGeminiFile 쪽 후속(거대파일 라이브 검증 필요).

export type AttachmentMode = "inline" | "files-api";

/**
 * 첨부를 inline(base64)로 보낼지 Files API로 업로드할지(순수).
 * @param base64Length 첨부 base64 문자열 길이(≈바이트의 4/3 — 보수적이라 한도를 약간 일찍 넘겨 안전).
 * @param inlineMaxBytes inline 허용 상한(바이트, env GEMINI_INLINE_MAX_BYTES). 초과면 Files API.
 */
export function attachmentMode(base64Length: number, inlineMaxBytes: number): AttachmentMode {
  return base64Length > inlineMaxBytes ? "files-api" : "inline";
}

