// ── I 배치 결과 요약 (PLAN-multi-upload §I) ──────────────────────────────────────────────
// 멀티 업로드/분석 후 "신규 N · 중복 M · 실패 K · 검토 L" 배너용 순수 집계. dedup(중복)은 분석 시점에
//   SKIPPED_DUP로 드러나므로(ingestText), 자료들의 ★잡 상태★를 분류해 카운트한다. UI 배너는 후속.

export interface BatchSummary {
  applied: number;  // 신규 반영(APPLIED)
  duplicate: number; // 이미 분석된 중복(SKIPPED_DUP)
  failed: number;   // 실패(FAILED)
  review: number;   // 검토 대기(NEEDS_REVIEW)
  pending: number;  // 처리 중/대기(QUEUED·RUNNING·APPLYING·PENDING·UNANALYZED 등)
  total: number;
}

/** 자료들의 상태 문자열 목록 → 분류 카운트(순수). 알 수 없는/진행 상태는 pending으로 모은다. */
export function summarizeBatch(statuses: (string | null | undefined)[]): BatchSummary {
  const s: BatchSummary = { applied: 0, duplicate: 0, failed: 0, review: 0, pending: 0, total: statuses.length };
  for (const st of statuses) {
    switch (st) {
      case "APPLIED": s.applied++; break;
      case "SKIPPED_DUP": s.duplicate++; break;
      case "FAILED": s.failed++; break;
      case "NEEDS_REVIEW": s.review++; break;
      default: s.pending++; break; // QUEUED/RUNNING/APPLYING/PENDING/UNANALYZED/null 등
    }
  }
  return s;
}

/** 사람이 읽는 한 줄 요약("신규 2 · 중복 1 · 실패 0") — 0인 항목은 생략. 비면 빈 문자열. */
export function batchSummaryText(s: BatchSummary): string {
  const parts: string[] = [];
  if (s.applied) parts.push(`신규 ${s.applied}`);
  if (s.duplicate) parts.push(`중복 ${s.duplicate}`);
  if (s.review) parts.push(`검토 대기 ${s.review}`);
  if (s.failed) parts.push(`실패 ${s.failed}`);
  if (s.pending) parts.push(`처리 중 ${s.pending}`);
  return parts.join(" · ");
}

