import { describe, it, expect } from "vitest";
import { attachmentMode } from "../lib/attachments";

// ⓐ Gemini 첨부 경로 선택(순수) — inline vs Files API 경계.
const MB = 1024 * 1024;
const INLINE_MAX = 15 * MB;

describe("attachmentMode", () => {
  it("한도 이하 base64는 inline", () => {
    expect(attachmentMode(1 * MB, INLINE_MAX)).toBe("inline");
    expect(attachmentMode(INLINE_MAX, INLINE_MAX)).toBe("inline"); // 정확히 한도 = inline(초과 아님)
  });
  it("한도 초과 base64는 Files API", () => {
    expect(attachmentMode(INLINE_MAX + 1, INLINE_MAX)).toBe("files-api");
    expect(attachmentMode(200 * MB, INLINE_MAX)).toBe("files-api");
  });
  it("임계는 env로 조정 가능(작은 한도로 강제 Files API)", () => {
    expect(attachmentMode(5000, 4096)).toBe("files-api");
  });
});

