  groqLimitBytes: number,
  ffmpegAvailable: boolean,
  geminiOptIn: boolean,
): boolean {
  return sizeBytes > groqLimitBytes && !ffmpegAvailable && !geminiOptIn;
}

// ── J 전사 비동기화: 진행률 매핑 (PLAN-remaining-backlog-design §6) ──────────────────────
// 전사를 분석 잡의 ★전반부(0~40%)★로 표시 — 이후 응축(요약)·분석이 뒤를 채운다. 순수·테스트.
export function sttProgressPct(done: number, total: number): number {
  if (total <= 0) return 0;
  const frac = Math.min(1, Math.max(0, done / total));
  return Math.round(frac * 40);
}

