const isAudioSrc = isTranscribedExtractor(source.extractor) || isAudioVideoExt(rawExt, source.mimeType);
if (isAudioSrc && (opts.diarize || !source.normalizedPath)) {
  const r = await transcribe(rawBytes, source.originalName ?? source.title, source.mimeType ?? "audio/mpeg", { diarize: opts.diarize });
  if (!r.text.trim() || r.quality === "none") {
    throw new Error("음성을 텍스트로 변환하지 못했습니다. 잠시 후 다시 시도하거나 음성을 더 짧게 잘라 올려주세요.");
  }
  const condensed = await condenseTextForIngest(r.text, { model: opts.model, provider, signal: opts.signal, jobId: opts.jobId });
  return ingestText({ ...base, type: source.type, text: condensed, extractor: r.extractor, extractStatus: "FULL", normalizedText: r.text, augment, preservePath });
}

