import { describe, it, expect } from "vitest";
import { collapseTranscriptLoops, isTranscribedExtractor, oversizeAudioNeedsSplit } from "../lib/transcript";

const MB = 1024 * 1024;
const LIMIT = 25 * MB;

// 전사 품질 가드(PLAN-multi-upload §F) — 환각 반복 루프 접기. 불변식: 루프 없으면 원문 그대로(회귀0).

describe("collapseTranscriptLoops", () => {
  it("연속 동일 짧은 구절 ×6 → 1주기로 접고 생략 표시", () => {
    const t = "정상 도입부 문장입니다. 아, 그래. 아, 그래. 아, 그래. 아, 그래. 아, 그래. 아, 그래.";
    const { text, info } = collapseTranscriptLoops(t);
    expect(info.collapsed).toBe(true);
    expect(info.removed).toBeGreaterThanOrEqual(5);
    expect(text).toContain("정상 도입부"); // 앞부분 보존
    expect(text).toContain("전사 환각"); // 생략 표시
    // 반복 구절은 1회만 남는다(원래 6회) — 마커 오버헤드는 작은 입력에서만 두드러짐
    expect((text.match(/아, 그래/g) || []).length).toBeLessThanOrEqual(2);
  });

  it("주기적 A·B 반복 ×4 → 접는다", () => {
    const t = "아, 그래. 아, 안 줬어. 아, 그래. 아, 안 줬어. 아, 그래. 아, 안 줬어. 아, 그래. 아, 안 줬어.";
    const { info } = collapseTranscriptLoops(t);
    expect(info.collapsed).toBe(true);
    expect(info.removed).toBeGreaterThanOrEqual(6);
  });

  it("★루프 없는 정상 전사는 원문 그대로★(회귀0)", () => {
    const t = "오늘 회의에서는 3분기 매출을 검토했습니다. 김부장이 신규 계약 두 건을 보고했고, 이부장은 채용 계획을 공유했습니다. 다음 주까지 예산안을 확정하기로 했습니다.";
    const { text, info } = collapseTranscriptLoops(t);
    expect(info.collapsed).toBe(false);
    expect(info.removed).toBe(0);
    expect(text).toBe(t); // ★완전 동일★
  });

  it("임계 미만 반복(×3)은 건드리지 않음 — 정상 반복 보호", () => {
    const t = "네. 네. 네."; // 3회 — minRepeats(4) 미만
    const { text, info } = collapseTranscriptLoops(t);
    expect(info.collapsed).toBe(false);
    expect(text).toBe(t);
  });

  it("긴 문단 반복은 환각으로 보지 않음(maxUnitLen 보호)", () => {
    const long = "이것은 정상적으로 반복될 수 있는 충분히 긴 문장으로 환각 루프가 아니며 회의록에서 강조를 위해 의도적으로 다시 언급될 수 있는 내용입니다.";
    const t = [long, long, long, long].join(" ");
    const { info } = collapseTranscriptLoops(t);
    expect(info.collapsed).toBe(false);
  });

