// ── 원본(raw) 스토리지 추상화 (PLAN-remaining-backlog-design §9 — MinIO 대비) ──────────────
// raw 바이트는 현재 위키 git 작업트리(`raw/<scope>/<yyyy>/<mm>/<sha>.<ext>`)에 파일로 둔다(FsRawStore).
//   대용량(500MB)·무한증가 시 PVC 압박 → 오브젝트 스토리지(MinIO/S3)로 옮길 수 있게 ★스토리지 seam★을 둔다.
//   이 모듈은 ★인터페이스 + FS 구현 + 키매핑★까지(의존성 0). S3RawStore 실구현은 인프라·SDK 동반 후속(라이브).
import { promises as fs } from "node:fs";
import path from "node:path";
import { atomicWriteFile } from "./atomicWrite";

export interface RawStore {
  read(rawRel: string): Promise<Buffer>;
  exists(rawRel: string): Promise<boolean>;
  write(rawRel: string, bytes: Buffer): Promise<void>;
  delete(rawRel: string): Promise<void>;
}

// raw 상대경로 → 오브젝트 스토리지 키(순수). 현재는 동일 경로(접두 정규화만) — 버킷 내 같은 계층 유지.
//   선행 슬래시·중복 슬래시 제거(S3 키는 선행 '/'를 빈 폴더로 취급해 혼란).
export function rawRelToObjectKey(rawRel: string): string {
  return rawRel.replace(/^\/+/, "").replace(/\/{2,}/g, "/");
}

// 파일시스템 구현(현행 동작과 동일) — baseDir 하위에 rawRel로 입출력. 테스트는 임시 baseDir로 격리 가능.
export class FsRawStore implements RawStore {
  constructor(private baseDir: string) {}
  private abs(rawRel: string): string {
    // ★경로 탈출 방지★: 정규화 후 baseDir 밖이면 거부(ACL 경계 — 메모리 human-readable-attribution 인접).
    const p = path.resolve(this.baseDir, rawRel);
    if (p !== this.baseDir && !p.startsWith(this.baseDir + path.sep)) throw new Error("raw 경로가 baseDir를 벗어납니다.");
    return p;
  }
  async read(rawRel: string): Promise<Buffer> {
    return fs.readFile(this.abs(rawRel));
  }
  async exists(rawRel: string): Promise<boolean> {
    try { await fs.access(this.abs(rawRel)); return true; } catch { return false; }
  }
  async write(rawRel: string, bytes: Buffer): Promise<void> {
    const abs = this.abs(rawRel);
    await fs.mkdir(path.dirname(abs), { recursive: true });
    await atomicWriteFile(abs, bytes); // 원자적(temp→rename) — 부분쓰기 방지(무중단 배포 안전)
  }
  async delete(rawRel: string): Promise<void> {
    try { await fs.unlink(this.abs(rawRel)); } catch { /* 이미 없음 */ }
  }
}

// S3/MinIO 구현 ★스텁★ — 키매핑은 준비됨. 실제 입출력은 SDK·버킷 설정·라이브 검증 동반 후속(§9).
//   (의존성 추가 시 ★Linux Docker로 lockfile★ 생성 필수 — 메모리 npm-ci-lockfile-sync.)
export class S3RawStoreStub implements RawStore {
  constructor(public bucket: string) {}
  private key(rawRel: string): string { return rawRelToObjectKey(rawRel); }
  async read(rawRel: string): Promise<Buffer> { throw new Error(`S3RawStore 미구현(read ${this.bucket}/${this.key(rawRel)}) — 인프라 동반 후속`); }
  async exists(_rawRel: string): Promise<boolean> { return false; }
  async write(rawRel: string, _bytes: Buffer): Promise<void> { throw new Error(`S3RawStore 미구현(write ${this.bucket}/${this.key(rawRel)})`); }
  async delete(_rawRel: string): Promise<void> { /* no-op 스텁 */ }
}

