import { promises as fs } from "node:fs";

// ★원자적 파일 쓰기★ — 임시 파일에 다 쓴 뒤 rename으로 ★한 번에★ 교체("수정테이프로 갈아끼우기").
//   다중 파드/무중단 배포에서 읽기 파드가 같은 working-tree를 동시에 읽어도 ‘반쯤 쓰인’ 파일을 절대 보지 않게 한다.
//   rename은 같은 파일시스템에서 원자적(POSIX·CephFS·NTFS 모두 기존 파일 덮어쓰기 지원).
let seq = 0;
export async function atomicWriteFile(abs: string, data: string | Uint8Array): Promise<void> {
  const tmp = `${abs}.tmp-${process.pid}-${seq++}`;
  // 문자열은 utf8, Uint8Array(첨부 등 바이너리)는 그대로 기록(인코딩 무시).
  await fs.writeFile(tmp, data);
  try {
    await fs.rename(tmp, abs); // 원자적 교체
  } catch (e) {
    await fs.rm(tmp, { force: true }).catch(() => {});
    throw e;
  }
}

