// ── 청크/resumable 업로드 순수 헬퍼 (PLAN-remaining-backlog-design §8) ──────────────────────
// GB급·불안정망 대비: 클라가 큰 파일을 고정 크기 청크로 쪼개 순차 전송, 서버가 offset 검증하며 temp에 append,
//   전부 받으면 finalize(sha 검증→스테이징). 끊겨도 ★실패 청크만 재시도★. 의존성 0(node fs append).
// ★이 모듈은 순수 계획·검증 로직만★(엔드포인트·실제 append는 라이브 검증 동반 후속). 테스트 용이.

export interface ChunkSpec { index: number; start: number; end: number; size: number } // end=배타적

/** 총 바이트를 chunkBytes 크기 청크들로 분할 계획(순수). 마지막 청크는 나머지. */
export function planChunks(totalBytes: number, chunkBytes: number): ChunkSpec[] {
  if (totalBytes <= 0 || chunkBytes <= 0) return [];
  const out: ChunkSpec[] = [];
  let start = 0, index = 0;
  while (start < totalBytes) {
    const end = Math.min(start + chunkBytes, totalBytes);
    out.push({ index, start, end, size: end - start });
    start = end; index++;
  }
  return out;
}

/** 다음에 기대하는 offset(현재까지 받은 바이트)과 클라가 보낸 offset이 맞는지(순수·idempotent 재시도 판정).
 *  - got === expected → "ok"(이어받기) · got < expected → "duplicate"(이미 받음·무시) · got > expected → "gap"(거부). */
export function classifyChunkOffset(expectedOffset: number, gotOffset: number): "ok" | "duplicate" | "gap" {
  if (gotOffset === expectedOffset) return "ok";
  if (gotOffset < expectedOffset) return "duplicate";
  return "gap";
}

/** 누적 수신 바이트가 총 크기에 도달했는지(완료 판정, 순수). */
export function isUploadComplete(receivedBytes: number, totalBytes: number): boolean {
  return totalBytes > 0 && receivedBytes >= totalBytes;
}

