// ── H 파일별/그룹 추천 (PLAN-multi-upload §H) ──────────────────────────────────────────────
// 멀티 업로드 시 형식 제각각 파일을 ★추천 모델별 그룹★으로 묶어("전사본 2→Groq", "스캔PDF 1→Gemini")
//   그룹 단위 오버라이드. 기본=파일별 서버 reco. 순수 그룹화(입력순 안정) — UI 결선은 후속.
export interface StagedItem { id: number; recoModel: string; title?: string }
export interface ModelGroup { model: string; ids: number[]; titles: string[] }

/** 스테이징 파일들을 추천 모델별로 묶는다(순수). 그룹은 ★처음 등장한 모델 순서★ 유지(입력 안정). */
export function groupStagedByModel(items: StagedItem[]): ModelGroup[] {
  const order: string[] = [];
  const byModel = new Map<string, ModelGroup>();
  for (const it of items) {
    const m = it.recoModel || "(미지정)";
    let g = byModel.get(m);
    if (!g) { g = { model: m, ids: [], titles: [] }; byModel.set(m, g); order.push(m); }
    g.ids.push(it.id);
    g.titles.push(it.title ?? String(it.id));
  }
  return order.map((m) => byModel.get(m)!);
}

