import { describe, it, expect, beforeAll, afterAll } from "vitest";
import { mkdtemp, rm } from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { FsRawStore, S3RawStoreStub, rawRelToObjectKey } from "../lib/wiki/rawStore";

// MinIO 대비 스토리지 추상화(PLAN-remaining §9) — FsRawStore 실동작 + 키매핑 + 경로탈출 가드.
describe("rawRelToObjectKey", () => {
  it("선행/중복 슬래시 정규화, 동일 계층 유지", () => {
    expect(rawRelToObjectKey("raw/common/2026/06/abc.pdf")).toBe("raw/common/2026/06/abc.pdf");
    expect(rawRelToObjectKey("/raw//common/x.pdf")).toBe("raw/common/x.pdf");
  });
});

describe("FsRawStore", () => {
  let dir: string;
  beforeAll(async () => { dir = await mkdtemp(path.join(os.tmpdir(), "rawstore-")); });
  afterAll(async () => { await rm(dir, { recursive: true, force: true }); });

  it("write→read 라운드트립(바이너리 보존)", async () => {
    const store = new FsRawStore(dir);
    const rel = "raw/common/2026/06/deadbeef.bin";
    const bytes = Buffer.from([0, 1, 2, 255, 254, 10]);
    await store.write(rel, bytes);
    expect(await store.exists(rel)).toBe(true);
    expect(Buffer.compare(await store.read(rel), bytes)).toBe(0);
  });

  it("delete 후 exists=false, 재삭제 안전(이미 없음)", async () => {
    const store = new FsRawStore(dir);
    const rel = "raw/common/2026/06/tobedeleted.bin";
    await store.write(rel, Buffer.from("x"));
    await store.delete(rel);
    expect(await store.exists(rel)).toBe(false);
    await expect(store.delete(rel)).resolves.toBeUndefined(); // 재삭제 throw 안 함
  });

  it("★경로 탈출 거부★(baseDir 밖 접근 차단)", async () => {
    const store = new FsRawStore(dir);
    await expect(store.read("../../etc/passwd")).rejects.toThrow(/baseDir/);
    await expect(store.write("../escape.bin", Buffer.from("x"))).rejects.toThrow(/baseDir/);
  });
});

describe("S3RawStoreStub", () => {
  it("키매핑은 동작, 입출력은 미구현 명시", async () => {
    const s = new S3RawStoreStub("llm-wiki-raw");
    await expect(s.read("raw/x.pdf")).rejects.toThrow(/미구현/);
    expect(await s.exists("raw/x.pdf")).toBe(false);
  });
});

