import { planChunks, classifyChunkOffset, isUploadComplete } from "../lib/uploadChunks";

// 청크/resumable 업로드 순수 헬퍼(PLAN-remaining §8).
describe("planChunks", () => {
  it("균등 분할 + 마지막 나머지", () => {
    const c = planChunks(25, 10);
    expect(c).toEqual([
      { index: 0, start: 0, end: 10, size: 10 },
