import { describe, it, expect } from "vitest";
import { summarizeBatch, batchSummaryText } from "../lib/uploadBatch";

// I 배치 결과 요약(순수) — 신규/중복/실패/검토/처리중 분류.
describe("summarizeBatch", () => {
  it("상태별로 분류해 카운트한다", () => {
    const s = summarizeBatch(["APPLIED", "APPLIED", "SKIPPED_DUP", "FAILED", "NEEDS_REVIEW", "RUNNING", null]);
    expect(s).toEqual({ applied: 2, duplicate: 1, failed: 1, review: 1, pending: 2, total: 7 });
  });
  it("알 수 없는/진행 상태는 pending으로 모은다", () => {
    const s = summarizeBatch(["QUEUED", "APPLYING", "UNANALYZED", undefined, "WAT"]);
    expect(s.pending).toBe(5);
    expect(s.total).toBe(5);
  });
  it("빈 배치는 전부 0", () => {
    expect(summarizeBatch([])).toEqual({ applied: 0, duplicate: 0, failed: 0, review: 0, pending: 0, total: 0 });
  });
});

describe("batchSummaryText", () => {
  it("0인 항목은 생략하고 한 줄로", () => {
    expect(batchSummaryText(summarizeBatch(["APPLIED", "APPLIED", "SKIPPED_DUP"]))).toBe("신규 2 · 중복 1");
  });
  it("전부 0이면 빈 문자열", () => {
    expect(batchSummaryText(summarizeBatch([]))).toBe("");
  });
  it("실패·검토도 표시", () => {
    expect(batchSummaryText(summarizeBatch(["FAILED", "NEEDS_REVIEW"]))).toBe("검토 대기 1 · 실패 1");
  });
});

