// ─────────────────────────────────────────────────────────────────────────────
// 스캔/이미지 PDF의 ★페이지 래스터 + 다운스케일★ (docs/PLAN-model-prompt-strategy §6.7).
//
// 배경: 스캔 PDF는 텍스트가 없어 추출이 0 → 비전 모델에 ‘원본 PDF’를 첨부해야 하는데,
//   ① codex 등은 PDF 문서 첨부를 못 받고, ② Gemini는 페이지 이미지 해상도가 과대하면 400 INVALID_ARGUMENT.
//   (실측: A4 4장이 72.6MB = 페이지당 1918×9920px·19MP 초고DPI 스캔 → Gemini 거부.)
// 해결: pdfjs로 각 페이지의 내장 이미지를 꺼내 sharp로 ★적정 해상도 JPEG★로 줄여 ‘이미지’로 보낸다
//   (72.6MB → 405KB, Gemini 200·정확 인식 검증). Gemini·codex 양쪽 동작, 새 네이티브 의존성 0(pdfjs·sharp 기설치).
//   ★다운스케일은 분석 입력만★ — 원본(raw)은 보존되므로 영구 품질 손실이 아니다(사용자에게 명시 표시).
// ─────────────────────────────────────────────────────────────────────────────

export interface PdfPageImage {
  mediaType: string; // "image/jpeg"
  dataBase64: string;
  width: number; // 다운스케일 후
  height: number;
  origWidth: number; // 원본 픽셀
  origHeight: number;
}

export interface PdfImagesResult {
  images: PdfPageImage[];
  downscaled: boolean; // 한 장이라도 축소됐는가(=품질 안내 표시 트리거)
  maxEdge: number;
  pageCount: number; // PDF 전체 페이지 수
  extractedPages: number; // 이미지를 얻은 페이지 수
  truncated: number; // maxPages 상한으로 건너뛴 페이지 수
}

function envInt(name: string, dflt: number): number {
  return Number(process.env[name] || 0) || dflt;
}

// 순수: 긴 변이 maxEdge를 넘으면 ★비율 유지★로 축소(확대 안 함). 테스트 가능.
export function computeDownscale(w: number, h: number, maxEdge: number): { width: number; height: number; downscaled: boolean } {
  const longest = Math.max(w, h);
  if (longest <= maxEdge || longest <= 0) return { width: w, height: h, downscaled: false };
  const scale = maxEdge / longest;
  return { width: Math.max(1, Math.round(w * scale)), height: Math.max(1, Math.round(h * scale)), downscaled: true };
}

