// ★핵심 검증된 규칙★: 이미지명이 'g_'로 시작하면 문서 전역(commonObjs), 아니면 페이지 로컬(objs)에서 받는다(pdfjs v6).
//   비동기 디코드라 콜백+타임아웃으로 안전하게.
function getImageObject(page: PdfPage, name: string): Promise<PdfImageObj | null> {
  const store = name.startsWith("g_") ? page.commonObjs : page.objs;
  return new Promise((resolve) => {
    let done = false;
    try {
      store.get(name, (o) => { done = true; resolve(o ?? null); });
    } catch {
      resolve(null);
      return;
    }
    setTimeout(() => { if (!done) resolve(null); }, envInt("PDF_RASTER_TIMEOUT_MS", 15000));
  });
}

// PDF 각 페이지의 ★가장 큰 내장 이미지★를 꺼내 다운스케일 JPEG로 변환. 스캔 PDF(페이지=한 장 이미지)에 최적.
//   벡터/텍스트만인 페이지나 추출 실패 페이지는 건너뛴다(부분 성공 허용 — extractedPages로 보고).
export async function extractPdfPageImages(
  buf: Buffer,
  opts?: { maxEdge?: number; quality?: number; maxPages?: number; signal?: AbortSignal },
): Promise<PdfImagesResult> {
  const maxEdge = opts?.maxEdge ?? envInt("PDF_RASTER_MAX_EDGE", 2200);
  const quality = opts?.quality ?? envInt("PDF_RASTER_QUALITY", 82);
  const maxPages = opts?.maxPages ?? envInt("PDF_RASTER_MAX_PAGES", 50);

  const pdfjs = await import("pdfjs-dist/legacy/build/pdf.mjs");
  const doc = await pdfjs.getDocument({ data: new Uint8Array(buf) }).promise;
  const OPS = pdfjs.OPS;
  const pageCount = doc.numPages;
  const n = Math.min(pageCount, maxPages);
  const images: PdfPageImage[] = [];
  let downscaled = false;

  for (let i = 1; i <= n; i++) {
    if (opts?.signal?.aborted) throw new Error("분석이 취소되었습니다.");
    const page = (await doc.getPage(i)) as unknown as PdfPage;
    const ops = await page.getOperatorList();
    const names: string[] = [];
    for (let k = 0; k < ops.fnArray.length; k++) {
      if (ops.fnArray[k] === OPS.paintImageXObject) names.push(ops.argsArray[k][0] as string);
    }
    // 페이지에서 가장 큰(픽셀수) 이미지 선택 — 스캔은 보통 1장이지만 다중이면 본문 스캔이 가장 큼.
    let best: Required<PdfImageObj> | null = null;
    for (const name of names) {
      const img = await getImageObject(page, name);
      if (img?.data && img.width && img.height && img.kind != null) {
        if (!best || img.width * img.height > best.width * best.height) {
          best = { data: img.data, width: img.width, height: img.height, kind: img.kind };
        }
      }
    }
    page.cleanup?.();
    if (!best) continue;

    // kind: 1=GRAY_1BPP, 2=RGB_24BPP, 3=RGBA_32BPP. raw 길이가 안 맞으면(1bpp 패킹 등) 안전상 건너뜀.
    const channels = best.kind === 3 ? 4 : best.kind === 2 ? 3 : 1;
    if (best.data.length < best.width * best.height * channels) continue;

    const dim = computeDownscale(best.width, best.height, maxEdge);
    if (dim.downscaled) downscaled = true;
    try {
      const jpg = await sharp(Buffer.from(best.data.buffer, best.data.byteOffset, best.data.byteLength), {
        raw: { width: best.width, height: best.height, channels },
      })
        .resize({ width: dim.width, height: dim.height, fit: "fill" })
        .jpeg({ quality })
        .toBuffer();
      images.push({
        mediaType: "image/jpeg",
        dataBase64: jpg.toString("base64"),
        width: dim.width,
        height: dim.height,
        origWidth: best.width,
        origHeight: best.height,
      });
    } catch {
      /* 이 페이지 변환 실패 → 건너뜀(부분 성공 허용) */
    }
  }

  return { images, downscaled, maxEdge, pageCount, extractedPages: images.length, truncated: pageCount > n ? pageCount - n : 0 };
}

